-- +goose Up
-- Consolidated Postgres baseline, generated by `pg_dump --schema-only -n public -n tf`.
-- Pre-baseline Postgres installs are refused at boot. Down is a no-op.
--
-- Editing policy: multi mode has not shipped, so no Postgres install exists to
-- migrate and this baseline is MUTABLE - fold schema changes in place. Once multi
-- mode ships it freezes and later changes go in new NNN-numbered files here. (The
-- SQLite twin ships, so it takes forward migrations instead.)
--
-- Deliberate divergence from the SQLite twin - do NOT converge these:
--   1. Native enums and uuid/timestamptz/jsonb/interval/array here; TEXT/INTEGER
--      plus CHECKs there.
--   2. Composite (id, org_id) FKs and uniques so RLS can pin tenant scope; SQLite
--      uses single-column FKs (one connection, no RLS).
--   3. Attribution refs (creator_user_id and the like) are FK-constrained here,
--      bare TEXT there - local mode is N=1 and its sentinel user is never deleted.
--      Identity/ownership user_id PKs carry the users(id) FK in both dialects.
--   4. instance_config is SQLite-only; sessions is PG-only (multi-mode auth).
--   5. RLS policies, tf.* helpers, the auth.users FK and admin-only columns
--      (orgs.owner_user_id, teams.created_by_user_id, users.default_org_id,
--      sessions.active_org_id) are PG-only.
--   6. blueprint_runs.status has a CHECK here, app-validated there; same values.
--
-- Target image supabase/postgres:15.1.0.147 preloads supabase_vault and pgsodium;
-- TF uses neither, and drops the vault extension below.

CREATE SCHEMA IF NOT EXISTS tf;

-- The image ships `authenticator` (LOGIN, NOINHERIT); tf_app is NOLOGIN with RLS
-- enforced, and authenticator switches into it via SET LOCAL ROLE.
-- +goose StatementBegin
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'tf_app') THEN
    CREATE ROLE tf_app NOLOGIN NOINHERIT;
  END IF;
END
$$;
-- +goose StatementEnd

GRANT tf_app TO authenticator;

GRANT USAGE ON SCHEMA public, tf TO tf_app;

-- Least-privilege executor role. BYPASSRLS reproduces the *System store methods'
-- RLS bypass; the enumerated GRANTs at the end of this file are the real boundary.
-- +goose StatementBegin
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'tf_system') THEN
    CREATE ROLE tf_system NOLOGIN NOINHERIT BYPASSRLS;
  END IF;
END
$$;
-- +goose StatementEnd

-- The image pre-creates supabase_vault; TF doesn't use it, so drop the callable
-- SQL surface. The preloaded C library stays (image-managed) but is unreachable.
DROP EXTENSION IF EXISTS supabase_vault CASCADE;

-- pg_dump emits functions before the tables some bodies reference (e.g.
-- tf.team_in_current_org -> teams); bodies are still parsed at first invocation.
SET check_function_bodies = false;


CREATE TYPE public.membership_role AS ENUM (
    'admin',
    'member',
    'viewer'
);


CREATE TYPE public.org_role AS ENUM (
    'owner',
    'admin',
    'member'
);


-- +goose StatementBegin
CREATE FUNCTION tf.current_org_id() RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE
    WHEN current_setting('request.jwt.claims', true) IS NULL
      OR current_setting('request.jwt.claims', true) = ''
    THEN NULL
    ELSE NULLIF(current_setting('request.jwt.claims', true)::jsonb ->> 'org_id', '')::uuid
  END;
$$;
-- +goose StatementEnd


-- +goose StatementBegin
CREATE FUNCTION tf.current_user_id() RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE
    WHEN current_setting('request.jwt.claims', true) IS NULL
      OR current_setting('request.jwt.claims', true) = ''
    THEN NULL
    ELSE NULLIF(current_setting('request.jwt.claims', true)::jsonb ->> 'sub', '')::uuid
  END;
$$;
-- +goose StatementEnd


-- +goose StatementBegin
CREATE FUNCTION tf.guard_org_owner_transfer() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id THEN
    IF OLD.owner_user_id IS DISTINCT FROM tf.current_user_id() THEN
      RAISE EXCEPTION 'only the current org owner can transfer ownership'
        USING ERRCODE = '42501';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM org_memberships
       WHERE user_id = NEW.owner_user_id
         AND org_id  = NEW.id
         AND role    = 'owner'
    ) THEN
      RAISE EXCEPTION 'new owner_user_id must already have role=owner in org_memberships'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd


-- SECURITY DEFINER so the owner count reads past RLS: on a self-leave the caller's
-- own membership row is already gone, so an INVOKER read raises a false 23514.
-- +goose StatementBegin
CREATE FUNCTION tf.guard_org_owners() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM affected ao
    WHERE NOT EXISTS (
      SELECT 1 FROM org_memberships
       WHERE org_id = ao.org_id AND role = 'owner'
    )
  ) THEN
    RAISE EXCEPTION 'each org must retain at least one owner role'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$$;
-- +goose StatementEnd


-- +goose StatementBegin
CREATE FUNCTION tf.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;
-- +goose StatementEnd


-- +goose StatementBegin
CREATE FUNCTION tf.team_in_current_org(target_team uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM teams
    WHERE id = target_team
      AND org_id = tf.current_org_id()
  );
$$;
-- +goose StatementEnd


-- +goose StatementBegin
CREATE FUNCTION tf.user_has_org_access(target_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM org_memberships
    WHERE user_id = tf.current_user_id() AND org_id = target_org
  );
$$;
-- +goose StatementEnd


-- Reads one blueprint's running-ness past the creator-scoped blueprint_runs_select
-- policy, so the resume CAS refuses to un-terminal a completed conversation whose
-- blueprint is still running even for a non-creator caller (a plain subquery would
-- find nothing and fail open). With request claims p_org_id must equal the caller's
-- org; with none (admin pool) that check is skipped. Pinned search_path blocks
-- definer hijacking; a NULL id or a missing row answers false.
-- +goose StatementBegin
CREATE FUNCTION tf.blueprint_run_is_running(p_id uuid, p_org_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_id IS NULL THEN
    RETURN false;
  END IF;
  IF tf.current_org_id() IS NOT NULL AND p_org_id <> tf.current_org_id() THEN
    RAISE EXCEPTION 'blueprint_run_is_running: requested org % does not match caller org %', p_org_id, tf.current_org_id();
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM blueprint_runs br
    WHERE br.id = p_id AND br.org_id = p_org_id AND br.status = 'running'
  );
END;
$$;
-- +goose StatementEnd


-- +goose StatementBegin
CREATE FUNCTION tf.user_in_team(target_team uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM memberships
    WHERE user_id = tf.current_user_id()
      AND team_id = target_team
  );
$$;
-- +goose StatementEnd


-- Write-path sibling of user_in_team: membership exists AND the role can write.
-- Team-scoped write policies gate on this, read policies keep user_in_team; that
-- split is what makes the viewer role read-only. The join to teams adds
-- deleted_at IS NULL, so an archived team is write-blocked at the row level for
-- every policy keyed on this, task-scoped mutations included.

-- +goose StatementBegin
CREATE FUNCTION tf.user_can_write_team(target_team uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM memberships m
    JOIN teams t ON t.id = m.team_id
    WHERE m.user_id = tf.current_user_id()
      AND m.team_id = target_team
      AND m.role IN ('admin', 'member')
      AND t.deleted_at IS NULL
  );
$$;
-- +goose StatementEnd


-- +goose StatementBegin
CREATE FUNCTION tf.user_is_org_admin(target_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM org_memberships
    WHERE user_id = tf.current_user_id()
      AND org_id = target_org
      AND role IN ('owner', 'admin')
  );
$$;
-- +goose StatementEnd


-- +goose StatementBegin
CREATE FUNCTION tf.user_is_org_admin_via_team(target_team uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM teams t
    WHERE t.id = target_team
      AND tf.user_is_org_admin(t.org_id)
  );
$$;
-- +goose StatementEnd


-- +goose StatementBegin
CREATE FUNCTION tf.user_is_team_admin(target_team uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM memberships m
    WHERE m.user_id = tf.current_user_id()
      AND m.team_id = target_team
      AND m.role = 'admin'
  );
$$;
-- +goose StatementEnd


-- +goose StatementBegin
CREATE FUNCTION tf.user_owns_org(target_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM orgs WHERE id = target_org AND owner_user_id = tf.current_user_id()
  );
$$;
-- +goose StatementEnd


SET default_tablespace = '';

SET default_table_access_method = heap;


CREATE TABLE public.agents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    display_name text DEFAULT 'Triage Factory Bot'::text NOT NULL,
    default_model text,
    default_autonomy_suitability real,
    github_pat_user_id uuid,
    github_org_login text,
    github_org_email text,
    jira_service_account_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


-- One row per LLM call made by a headless system job (scorer, repo profiler), with
-- the cost + token breakdown so org spend reconciles with the provider bill.
-- Org-level: scorer batches mix teams and entities carry no team. Admin-pool
-- writes; the app pool only reads, via the org-scoped RLS policy below.
CREATE TABLE public.system_llm_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    job text NOT NULL,
    model text NOT NULL,
    total_cost_usd real DEFAULT 0 NOT NULL,
    input_tokens integer DEFAULT 0 NOT NULL,
    output_tokens integer DEFAULT 0 NOT NULL,
    cache_read_tokens integer DEFAULT 0 NOT NULL,
    cache_creation_tokens integer DEFAULT 0 NOT NULL,
    duration_ms integer DEFAULT 0 NOT NULL,
    num_turns integer DEFAULT 0 NOT NULL,
    is_error boolean DEFAULT false NOT NULL,
    metadata_json text,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone DEFAULT now() NOT NULL,
    -- The agent invocation's session id - the only value unique per call (the
    -- caller-supplied TraceID is a per-job label reused across invocations). Backs
    -- the idempotency constraint below. NULL if the subprocess never minted one.
    trace_id text
);


-- Low-volume audit log of governance actions with no external entity: org/team
-- membership and role changes, credential bind and rotate. Capture only, no read
-- surface yet. Written on the APP pool in the SAME transaction as the action, so a
-- log-write failure rolls the action back. action is a free-text discriminator
-- (app-validated, no CHECK); actor_user_id is NULL for system writes.
CREATE TABLE public.access_change_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    actor_user_id uuid,
    action text NOT NULL,
    target_user_id uuid,
    team_id uuid,
    detail_json text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


-- Append-only audit log of record: one row per external write TF performs under an
-- ORG-scoped credential (org GitHub App, org Jira service account). Writes under an
-- individual user's own credential are excluded. Written in the same transaction as
-- the action wherever that action has a DB state change to compose with.
-- action is a free-text discriminator (app-validated, no CHECK); credential is
-- github_app or jira_org; conversation_id is ON DELETE SET NULL so the row outlives
-- a purge; actor_user_id is the human authorizer, NULL for an autonomous write.
-- dedup_key is the natural per-action key - a branch push is observed twice (pre-push
-- hook and git-proxy backstop) and carries a deterministic key so the twin collapses
-- under ON CONFLICT DO NOTHING. current_url is the only column an UPDATE may touch:
-- where the object lives now (reads serve COALESCE(current_url, url)).
CREATE TABLE public.external_actions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    team_id uuid,
    provider text NOT NULL,
    action text NOT NULL,
    target text NOT NULL,
    external_id text,
    url text,
    current_url text,
    from_state text,
    to_state text,
    conversation_id uuid,
    actor_user_id uuid,
    credential text NOT NULL,
    dedup_key text NOT NULL,
    detail_json text,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.entities (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    source text NOT NULL,
    source_id text NOT NULL,
    kind text NOT NULL,
    title text,
    url text,
    snapshot_json jsonb,
    description text DEFAULT ''::text NOT NULL,
    state text DEFAULT 'active'::text NOT NULL,
    owning_team_id uuid,
    -- Who ASKED for the work: the creator of the conversation whose run opened
    -- this pull request, stamped at the exec recording funnel. Provenance, not
    -- ownership -- owning_team_id is the structural-owner axis routing reads,
    -- and this must never be spelled as a second owner. NULL when a human
    -- opened the object directly, and for every event-triggered run.
    commissioned_by_user_id uuid,
    last_polled_at timestamp with time zone,
    closed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    -- CAS token on the tracker's snapshot write: without it a straggler ex-leader
    -- (a poll cycle in flight across a lease handoff) blindly overwrites a newer
    -- snapshot and loses a transition. Bumped by 1 on every snapshot write.
    poll_seq bigint DEFAULT 0 NOT NULL
);


CREATE TABLE public.entity_links (
    from_entity_id uuid NOT NULL,
    to_entity_id uuid NOT NULL,
    kind text NOT NULL,
    origin text NOT NULL,
    org_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.event_handlers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    creator_user_id uuid,
    team_id uuid NOT NULL,
    kind text NOT NULL,
    event_type text NOT NULL,
    scope_predicate_json jsonb,
    enabled boolean DEFAULT true NOT NULL,
    source text DEFAULT 'user'::text NOT NULL,
    -- Per-rule routing scope. TRUE adds the rule's team to a task's visibility even
    -- for entities the team doesn't own; FALSE keeps visibility riding ownership.
    -- Routing gates explicitWatchTeams on this column, not on source.
    applies_to_unowned boolean DEFAULT false NOT NULL,
    system_slug text,
    name text,
    default_priority real,
    sort_order integer,
    blueprint_id text,
    breaker_threshold integer,
    min_autonomy_suitability real,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    -- As on prompts and blueprints: user_modified is the shipped-content sync's
    -- "never clobber a user edit" signal, and deleted_at keeps
    -- (org_id, team_id, system_slug) occupied so sync never resurrects the row.
    user_modified boolean DEFAULT false NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT event_handlers_kind_check CHECK ((kind = ANY (ARRAY['rule'::text, 'trigger'::text]))),
    CONSTRAINT event_handlers_rule_shape CHECK (((kind <> 'rule'::text) OR ((blueprint_id IS NULL) AND (breaker_threshold IS NULL) AND (min_autonomy_suitability IS NULL) AND (name IS NOT NULL) AND (default_priority IS NOT NULL) AND (sort_order IS NOT NULL)))),
    -- source is app-validated, not CHECK-constrained, so new provenance values are
    -- addable without DDL. The creator pairing below tolerates any non-system source.
    CONSTRAINT event_handlers_system_has_no_creator CHECK ((((source = 'system'::text) AND (creator_user_id IS NULL)) OR ((source <> 'system'::text) AND (creator_user_id IS NOT NULL)))),
    CONSTRAINT event_handlers_trigger_shape CHECK (((kind <> 'trigger'::text) OR ((blueprint_id IS NOT NULL) AND (breaker_threshold IS NOT NULL) AND (min_autonomy_suitability IS NOT NULL) AND (default_priority IS NULL) AND (sort_order IS NULL) AND (name IS NULL))))
);


CREATE TABLE public.events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    entity_id uuid,
    event_type text NOT NULL,
    dedup_key text DEFAULT ''::text NOT NULL,
    metadata_json jsonb,
    occurred_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.events_catalog (
    id text NOT NULL,
    source text NOT NULL,
    category text NOT NULL,
    label text NOT NULL,
    description text NOT NULL
);


-- goose_db_version is managed by goose itself — do NOT recreate.


CREATE TABLE public.jira_project_status_rules (
    team_id uuid NOT NULL,
    project_key text NOT NULL,
    -- Members are jsonb arrays of {"id","name"} status refs; a canonical is one
    -- such object. The id is the identity and survives a Jira status rename; the
    -- name is a display snapshot from when the rule was saved.
    pickup_members jsonb DEFAULT '[]'::jsonb NOT NULL,
    in_progress_members jsonb DEFAULT '[]'::jsonb NOT NULL,
    in_progress_canonical jsonb,
    -- in_review is the OPTIONAL fourth rule. Its members reach neither the
    -- discovery JQL nor the stock deck, so an empty rule is complete and a status
    -- may appear in both in_progress_members and in_review_members.
    in_review_members jsonb DEFAULT '[]'::jsonb NOT NULL,
    in_review_canonical jsonb,
    done_members jsonb DEFAULT '[]'::jsonb NOT NULL,
    done_canonical jsonb,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    -- Mirror of the SQLite CHECKs: each write-target rule is complete-or-empty,
    -- the canonical being the status TF transitions into (pickup has none, so no
    -- constraint). "canonical is in members" needs a subquery — HTTP validator.
    CONSTRAINT jpsr_in_progress_complete_or_empty CHECK (
        (jsonb_array_length(in_progress_members) = 0 AND in_progress_canonical IS NULL)
        OR (jsonb_array_length(in_progress_members) > 0 AND in_progress_canonical IS NOT NULL)
    ),
    CONSTRAINT jpsr_in_review_complete_or_empty CHECK (
        (jsonb_array_length(in_review_members) = 0 AND in_review_canonical IS NULL)
        OR (jsonb_array_length(in_review_members) > 0 AND in_review_canonical IS NOT NULL)
    ),
    CONSTRAINT jpsr_done_complete_or_empty CHECK (
        (jsonb_array_length(done_members) = 0 AND done_canonical IS NULL)
        OR (jsonb_array_length(done_members) > 0 AND done_canonical IS NOT NULL)
    )
);


-- One row per (team, github_org_login, github_team_slug): a team routing a
-- GitHub team's review requests to itself. Dumb string labels, no membership
-- resolution. Pure key tuples — edits are replace-sets, so no UPDATE policy.
CREATE TABLE public.team_github_groups (
    team_id uuid NOT NULL,
    github_org_login text NOT NULL,
    github_team_slug text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tgg_org_login_populated CHECK (github_org_login <> ''),
    CONSTRAINT tgg_team_slug_populated CHECK (github_team_slug <> '')
);


-- One row per (team, repository): the repos a team tracks, distinct from
-- team_github_groups above (review routing). Referenced by registry id, so a
-- rename leaves every row here resolving. org_id is denormalized from the team
-- so both FKs are COMPOSITE, letting the DB check they share an org.
CREATE TABLE public.team_github_repos (
    team_id uuid NOT NULL,
    repository_id uuid NOT NULL,
    org_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.memberships (
    user_id uuid NOT NULL,
    team_id uuid NOT NULL,
    role public.membership_role DEFAULT 'member'::public.membership_role NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.org_memberships (
    user_id uuid NOT NULL,
    org_id uuid NOT NULL,
    role public.org_role DEFAULT 'member'::public.org_role NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.org_settings (
    org_id uuid NOT NULL,
    -- Defaults to https where the SQLite twin defaults to ssh — do not converge.
    -- Postgres means multi mode, where an SSH clone has nothing to authenticate
    -- with: a GitHub App installation token is an HTTPS bearer credential.
    github_clone_protocol text DEFAULT 'https'::text NOT NULL,
    -- org_secrets key refs, not raw secrets. NULL = the deployment default or
    -- not configured yet (self-host); rotation never touches this row.
    anthropic_api_key_ref text,
    bedrock_credentials_ref text,
    -- 'system' (host credentials, resolved by the SDK from the environment) or
    -- 'byok' (the org's own bound material); app-validated, no CHECK. Multi mode
    -- refuses 'system'; the SQLite twin defaults to it — do not converge.
    llm_auth_method text DEFAULT 'byok'::text NOT NULL,
    -- JSON array of the model keys this org's teams may pick from (native wire
    -- ids). NULL = no preference, resolving to every model the deployment offers;
    -- the resolved set is never stored. App-validated against the build catalog.
    enabled_models text,
    -- The modelcatalog key both headless system jobs (scorer, repo profiler) run
    -- on; app-validated. Empty = not picked, and those jobs skip their cycles.
    -- The SQLite twin defaults to 'claude-haiku-4-5-20251001' — do not converge.
    background_jobs_model text DEFAULT ''::text NOT NULL,
    -- Org-wide daily LLM spend cap. NULL (and 0, app-side) = no cap. At or above
    -- it, Spawner.Delegate refuses new runs; in-flight runs are unaffected and
    -- the read fails open.
    max_daily_cost_usd double precision,
    -- Per-org ceiling on concurrently running runs across the fleet. NULL (and
    -- <= 0, app-side) = unlimited. Enforced in ClaimNextRun, read live, and never
    -- interrupts an in-flight run. Local mode is N=1 and ignores it.
    max_concurrent_runs integer,
    -- Ship-dark org toggle for the within-org prompt marketplace. Default false:
    -- the UI renders it grayed out as "coming soon"; enforcement is not wired yet.
    marketplace_enabled boolean DEFAULT false NOT NULL,
    -- 'pat', 'byo_app', or 'managed_app' (the deployment's shared App, which no
    -- path writes yet); app-validated, no CHECK. Stated, not inferred: a missing
    -- org_github_apps row also describes an org on a shared App. UpdateSettings
    -- omits it; SetGitHubCredentialClass writes it.
    github_credential_class text DEFAULT 'pat'::text NOT NULL,
    -- Ceiling on how long any of the org's API tokens may live, in days. NULL
    -- (the default, and the SQLite twin's too) = uncapped. It is applied at USE
    -- rather than stamped into a token at mint — effective expiry is
    -- min(expires_at, created_at + cap) computed against the CURRENT cap — so
    -- tightening it immediately shortens every existing token in the org, with
    -- no grandfathering and no sweep job. Nothing folds it into a stored
    -- expires_at: a token's row records the expiry it was minted with, and this
    -- narrows that at every use.
    api_token_max_age_days integer CHECK (api_token_max_age_days IS NULL OR api_token_max_age_days BETWEEN 1 AND 365),
    -- Optimistic-concurrency token for the whole-row settings save: the read
    -- hands it to the client, the write requires it, a stale token gets 409, and
    -- there is no merge. Bumped by OrgsStore.UpdateSettings alone, and it covers
    -- org_settings only — the per-source PATCH is last-writer-wins.
    version integer DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT org_settings_github_clone_protocol_check CHECK ((github_clone_protocol = ANY (ARRAY['https'::text, 'ssh'::text])))
);


CREATE TABLE public.orgs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    description text,
    billing_email text,
    owner_user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone
);


CREATE TABLE public.pending_firings (
    id bigint NOT NULL,
    org_id uuid NOT NULL,
    creator_user_id uuid NOT NULL,
    entity_id uuid NOT NULL,
    task_id uuid NOT NULL,
    trigger_id uuid NOT NULL,
    triggering_event_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    skip_reason text,
    queued_at timestamp with time zone DEFAULT now() NOT NULL,
    -- claimed_at stamps a claiming pop (status -> 'draining'); cleared on release.
    -- The drain sweeper requeues 'draining' rows whose claim is stale.
    claimed_at timestamp with time zone,
    drained_at timestamp with time zone,
    fired_run_id uuid
);


CREATE SEQUENCE public.pending_firings_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE public.pending_firings_id_seq OWNED BY public.pending_firings.id;


CREATE TABLE public.poller_state (
    org_id uuid NOT NULL,
    source text NOT NULL,
    source_id text NOT NULL,
    state_json jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.prompts (
    id text DEFAULT (gen_random_uuid())::text NOT NULL,
    org_id uuid NOT NULL,
    creator_user_id uuid,
    team_id uuid NOT NULL,
    name text NOT NULL,
    body text NOT NULL,
    source text DEFAULT 'user'::text NOT NULL,
    usage_count integer DEFAULT 0 NOT NULL,
    hidden boolean DEFAULT false NOT NULL,
    user_modified boolean DEFAULT false NOT NULL,
    allowed_tools text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    model text DEFAULT ''::text NOT NULL,
    system_slug text,
    -- Soft delete. Hard delete is impossible: the blueprint step FK is RESTRICT
    -- and conversations.prompt_id has no ON DELETE action. Request-facing reads
    -- filter deleted_at IS NULL; the ...System reads still resolve it.
    deleted_at timestamp with time zone,
    -- source is app-validated, not CHECK-constrained. system_has_no_creator below
    -- is the only source invariant the DB enforces.
    CONSTRAINT prompts_system_has_no_creator CHECK ((((source = 'system'::text) AND (creator_user_id IS NULL)) OR ((source <> 'system'::text) AND (creator_user_id IS NOT NULL))))
);


-- The registry of the repositories TF works with, and the target every
-- repository reference in this schema points at. (source, external_id) is the
-- half of a repository identity a rename does not move; source is app-validated.
-- Durable: untracking never deletes it, since a worktree or task may name it.
CREATE TABLE public.repositories (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    owner text NOT NULL,
    repo text NOT NULL,
    source text DEFAULT 'github'::text NOT NULL,
    external_id text,
    description text,
    has_readme boolean DEFAULT false NOT NULL,
    has_claude_md boolean DEFAULT false NOT NULL,
    has_agents_md boolean DEFAULT false NOT NULL,
    profile_text text,
    clone_url text,
    default_branch text,
    base_branch text,
    clone_status text DEFAULT 'pending'::text NOT NULL,
    clone_error text,
    clone_error_kind text,
    profiled_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    pulls_etag text,
    pulls_polled_at timestamp with time zone
);


-- One row per external object a conversation produces (branch, PR, review,
-- issue, comment); provider + kind discriminate, writers UPSERT on
-- (org_id, dedup_key). team_id is denormalized from the conversation so reads
-- scope by team; conversation_id is nullable so the row survives a purge.
CREATE TABLE public.artifacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    conversation_id uuid,
    org_id uuid NOT NULL,
    team_id uuid NOT NULL,
    provider text NOT NULL,
    kind text NOT NULL,
    target text NOT NULL,
    external_id text,
    url text,
    state text NOT NULL,
    dedup_key text NOT NULL,
    details_json text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.conversation_memory (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    entity_id uuid NOT NULL,
    blueprint_run_id uuid,
    agent_content text,
    human_content text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


-- Lets one conversation_memory row reach every entity the run touched, not just
-- the denormalized entity_id above. Keyed on conversation_id because touches are
-- recorded mid-run, before the conversation_memory row exists. role is free text.
CREATE TABLE public.conversation_memory_entities (
    org_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    entity_id uuid NOT NULL,
    role text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


-- The transcript canon: one row per neutral (OpenAI-shaped) API message, owned
-- by exactly one conversation. Assembly is a pure function of these rows.
CREATE TABLE public.messages (
    id bigint NOT NULL,
    org_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    -- Stamps the whole turn: the requesting user's own row and the assistant/tool
    -- rows produced in response. NULL = system-triggered.
    user_id uuid,
    -- The executor engagement that produced this row, for per-engagement token
    -- accounting. NULL outside any claim. Never read by assembly.
    claim_id uuid,
    -- role is app-validated, no CHECK: 'assistant' | 'tool' | 'user'. Only rows
    -- deviating from normal role behavior carry a subtype. System-minted 'user'
    -- subtypes: 'injection:compaction-request', 'injection:compaction-result',
    -- 'injection:steer', 'injection:system-note', 'injection:context',
    -- 'injection:nudge', 'stop-note'.
    role text NOT NULL,
    content text,
    subtype text DEFAULT ''::text,
    tool_calls jsonb,
    tool_call_id text,
    is_error boolean DEFAULT false NOT NULL,
    metadata jsonb,
    model text,
    input_tokens integer,
    output_tokens integer,
    cache_read_tokens integer,
    cache_creation_tokens integer,
    -- Dollars settled at this row: NULL = not a settlement row, 0 = free. An
    -- invocation's total lands as one lump on its last recorded row, so SUM over
    -- a window is that window's spend. messages is the only such ledger.
    cost_usd real,
    -- The provider's own spelling of why this turn stopped ('end_turn' /
    -- 'max_tokens' / 'tool_use' / 'refusal' / …). Assistant rows only; NULL = not
    -- an assistant row, or a stream that reported none. Never an assembly input.
    stop_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    -- Array of reasoning-detail objects in bifrost's ChatReasoningDetails shape
    -- ({index, type, text?, signature?, data?}). Replayed verbatim, never
    -- reordered — the API validates each block's signature. NULL = no reasoning.
    reasoning jsonb,
    -- Array of neutral content blocks (text / image / file), any role. NULL means
    -- the flat `content` column is the whole story.
    content_blocks jsonb,
    -- delivered=false is a durable pending input (steer, follow-up, staged
    -- injection) not yet assembled; ordering is insertion order. Exactly-once
    -- consumption is the consumer's: a claiming UPDATE, or the claim fence.
    delivered boolean DEFAULT true NOT NULL,
    -- App-validated: 'active' | 'elided' (deterministic stub, content + is_error
    -- retained) | 'inactive' (superseded by compaction, never assembled). Flips
    -- are policy-gated and sticky.
    window_state text DEFAULT 'active'::text NOT NULL,
    -- Assembly-order override: the effective sort key is COALESCE(seq, id). NULL
    -- for appended rows; only a synthetic insertion sets a fractional value.
    seq double precision,
    -- Wall-clock milliseconds for this row's work — assistant: request issued →
    -- message complete; tool: dispatch → result; else NULL. NULL is "not
    -- measured", never "took no time"; time waiting on a human is excluded.
    duration_ms integer
);


CREATE SEQUENCE public.messages_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE public.messages_id_seq OWNED BY public.messages.id;


-- One row per (conversation, repository, ref) a run materialized. No ON DELETE
-- on the repository FK: deleting a repository a run names is refused, not cascaded.
CREATE TABLE public.conversation_worktrees (
    conversation_id uuid NOT NULL,
    org_id uuid NOT NULL,
    repository_id uuid NOT NULL,
    path text NOT NULL,
    ref text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


-- One row per durable agent transcript, whatever the surface. Execution state is
-- on claims; the transcript and its cost/token ledger are messages.
CREATE TABLE public.conversations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    -- 'delegation' | 'interactive' (reserved) | namespaced 'subagent:<kind>'
    -- (never the bare word). App-validated, no CHECK.
    type text DEFAULT 'delegation'::text NOT NULL,
    creator_user_id uuid,
    team_id uuid,
    visibility text DEFAULT 'team'::text NOT NULL,
    -- NULL unless the conversation descends from a task and a saved prompt;
    -- conversations_origin_requires_parents pins both for origin 'blueprint'.
    task_id uuid,
    prompt_id text,
    trigger_id uuid,
    trigger_type text DEFAULT 'manual'::text NOT NULL,
    -- Blueprint-step delegation vs other creation modes. App-validated, no CHECK.
    origin text DEFAULT 'blueprint'::text NOT NULL,
    -- 'sdk' (the Claude Code SDK subprocess) or 'native' (the executor-side loop
    -- hydrating from messages). App-validated, and a one-way ratchet: once an
    -- engagement runs native the SDK can never continue the transcript.
    runtime text DEFAULT 'sdk'::text NOT NULL,
    -- Outcome or nothing: 'open' (a park), a terminal ('completed' | 'failed'), or
    -- NULL mid-flight. Queued and running are derived from claims, never stored.
    status text,
    model text,
    -- SDK resume handle. NULL under runtime='native', where messages are truth.
    sdk_session_id text,
    worktree_path text,
    result_summary text,
    outcome text,
    outcome_reason text,
    -- Why status reached 'failed' (domain.RunFailureKind). NULL = unclassified.
    failure_kind text,
    -- Why the conversation was parked 'open' (domain.ParkReason). NULL = never
    -- parked, or resumed since. The model's stop reason lives on
    -- messages.stop_reason. The Go sets are the authority for both vocabularies.
    park_reason text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    -- Stamped on park, cleared on resume; the snapshot-retention sweep keys off it.
    parked_at timestamp with time zone,
    -- NULL = live. An archived conversation is never claimed again.
    archived_at timestamp with time zone,
    actor_agent_id uuid,
    -- Links a subagent conversation to its spawner. Scoping anchors (e.g. task_id)
    -- are denormalized from the parent at mint so RLS never recurses.
    parent_conversation_id uuid,
    blueprint_run_id uuid,
    blueprint_step_index integer,
    triggering_event_id uuid,
    -- Stamped once at enqueue, never bumped. The scheduler orders by started_at.
    queued_at timestamp with time zone,
    -- Placement affinity computed at enqueue and cleared on requeue; advisory,
    -- so no FK to instances.
    preferred_executor_id text,
    CONSTRAINT conversations_creator_matches_trigger_type CHECK ((((trigger_type = 'manual'::text) AND (creator_user_id IS NOT NULL)) OR ((trigger_type = 'event'::text) AND (creator_user_id IS NULL)))),
    CONSTRAINT conversations_team_visibility_requires_team CHECK (((visibility <> 'team'::text) OR (team_id IS NOT NULL))),
    CONSTRAINT conversations_visibility_check CHECK ((visibility = ANY (ARRAY['private'::text, 'team'::text, 'org'::text]))),
    CONSTRAINT conversations_origin_requires_parents CHECK (((origin = 'blueprint'::text AND blueprint_run_id IS NOT NULL AND task_id IS NOT NULL AND prompt_id IS NOT NULL) OR (origin <> 'blueprint'::text)))
);


CREATE TABLE public.sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    jwt_enc bytea NOT NULL,
    jwt_nonce bytea NOT NULL,
    refresh_token_enc bytea NOT NULL,
    refresh_nonce bytea NOT NULL,
    jwt_expires_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    user_agent text,
    ip_addr inet,
    active_org_id uuid,
    CONSTRAINT sessions_check CHECK ((expires_at > created_at)),
    CONSTRAINT sessions_check1 CHECK ((jwt_expires_at <= expires_at))
);


CREATE TABLE public.swipe_events (
    id bigint NOT NULL,
    org_id uuid NOT NULL,
    creator_user_id uuid NOT NULL,
    task_id uuid NOT NULL,
    action text NOT NULL,
    hesitation_ms integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE SEQUENCE public.swipe_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE public.swipe_events_id_seq OWNED BY public.swipe_events.id;


CREATE TABLE public.task_events (
    task_id uuid NOT NULL,
    event_id uuid NOT NULL,
    org_id uuid NOT NULL,
    kind text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    creator_user_id uuid NOT NULL,
    team_id uuid,
    visibility text DEFAULT 'team'::text NOT NULL,
    entity_id uuid NOT NULL,
    event_type text NOT NULL,
    dedup_key text DEFAULT ''::text NOT NULL,
    primary_event_id uuid NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    priority_score real,
    ai_summary text,
    autonomy_suitability real,
    priority_reasoning text,
    scoring_status text DEFAULT 'pending'::text NOT NULL,
    -- An owed post-scoring re-derive: the event-time trigger pass skips deferred
    -- (min_autonomy_suitability > 0) triggers on the promise a re-derive fires them
    -- once a score exists. Written with the scores; the scorer drains the owed set.
    rederive_owed boolean DEFAULT false NOT NULL,
    severity text,
    relevance_reason text,
    source_status text,
    snooze_until timestamp with time zone,
    close_reason text,
    close_event_type text,
    closed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    claimed_by_agent_id uuid,
    claimed_by_user_id uuid,
    CONSTRAINT tasks_claim_xor CHECK (((claimed_by_agent_id IS NULL) OR (claimed_by_user_id IS NULL))),
    CONSTRAINT tasks_claimed_requires_team CHECK ((((claimed_by_user_id IS NULL) AND (claimed_by_agent_id IS NULL)) OR (team_id IS NOT NULL))),
    CONSTRAINT tasks_visibility_check CHECK ((visibility = ANY (ARRAY['private'::text, 'team'::text, 'org'::text]))),
    CONSTRAINT tasks_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'in_progress'::text, 'in_review'::text, 'done'::text, 'dismissed'::text, 'snoozed'::text])))
);


-- Teams whose handlers matched the event that spawned the task. A team sees an
-- unclaimed task iff it is here or owns it; a claimed task consolidates to team_id.
CREATE TABLE public.task_teams (
    task_id uuid NOT NULL,
    team_id uuid NOT NULL
);


CREATE TABLE public.team_agents (
    team_id uuid NOT NULL,
    agent_id uuid NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    per_team_model text,
    per_team_autonomy_suitability real,
    added_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.team_settings (
    team_id uuid NOT NULL,
    jira_projects text[] DEFAULT '{}'::text[] NOT NULL,
    ai_reprioritize_threshold integer DEFAULT 5 NOT NULL,
    ai_preference_update_interval integer DEFAULT 20 NOT NULL,
    -- default_model is a concrete model id (a modelcatalog key), never a vendor
    -- tier word: it is dispatched verbatim and priced by that string. Partial
    -- upserts materialize the row without naming it.
    default_model text DEFAULT 'claude-sonnet-5'::text NOT NULL,
    auto_delegate_enabled boolean DEFAULT true NOT NULL,
    -- SDK permission posture: multi-mode SDK runs force auto, local mode honors
    -- this setting, native runs ignore it.
    auto_mode_enabled boolean DEFAULT true NOT NULL,
    -- Grace window (ms) an unattended permission prompt waits before denying with
    -- "no operator available"; the boolean off waits out the full timeout instead.
    permission_absent_grace_ms integer DEFAULT 15000 NOT NULL,
    permission_absent_autodeny_enabled boolean DEFAULT true NOT NULL,
    -- Per-team daily LLM spend cap, gated on the governance entitlement. NULL = no
    -- cap, and the app treats 0 the same; the team's spend for the current UTC day
    -- (its own team_id rows only) gates new runs. The read fails open.
    max_daily_cost_usd double precision,
    -- Free-text branch convention shown to the agent as guidance; the push gate is
    -- the enforcement point. The literal "<ticket-id>" is substituted at render
    -- time, and an empty write coalesces to the default.
    branch_template text DEFAULT 'tfac/<ticket-id>'::text NOT NULL,
    -- How a delegated agent's finalized review reaches GitHub. 'identity' (the
    -- default) decides from the acting credential: an App installation posts direct,
    -- a borrowed PAT or an indeterminate identity stages for approval. 'draft'
    -- always stages, 'auto' always submits, 'auto_unless_blocking' stages only
    -- REQUEST_CHANGES or a BLOCKER-severity comment. App-validated, no CHECK.
    review_posture text DEFAULT 'identity'::text NOT NULL,
    -- Whether a delegated agent may push to a repo's base / default branch:
    -- 'never' (the default) refuses, 'manual_only' permits it on a human-dispatched
    -- run only, 'always' permits it. Enforced at the per-run git proxy's ref gate
    -- (local mode: the pre-push hook). App-validated, no CHECK.
    base_branch_push_policy text DEFAULT 'never'::text NOT NULL,
    -- Which of the org's enabled models this team may pick from, as a JSON array
    -- of catalog keys. NULL inherits the org's set, which write and read narrow to.
    enabled_models text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.teams (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    description text,
    created_by_user_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    -- Soft-delete: archiving force-stops in-flight work and blocks writes.
    -- Request-facing reads filter deleted_at IS NULL; the ...System reads do not.
    deleted_at timestamp with time zone,
    -- NULL = the one-time grandfather backfill before the boot-time
    -- shipped-defaults sync is still owed for this team.
    shipped_defaults_backfilled_at timestamp with time zone
);


-- Per-user prefs. AI behavior policy is team-scoped (team_settings).
CREATE TABLE public.user_settings (
    user_id uuid NOT NULL,
    -- When this user last opened the Overview; the away line and counts anchor to
    -- it. Written by the page, not stamped on read. NULL = never opened.
    overview_seen_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    display_name text,
    avatar_url text,
    timezone text DEFAULT 'UTC'::text NOT NULL,
    default_org_id uuid,
    last_acting_team_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


-- Host-scoped GitHub identity bindings: one human can hold a different login on
-- each GitHub host, so the key is (user_id, github_base_url); an absent row is a
-- supported state. verified_at is the last authenticated /user confirmation
-- against the host, NULL when a login is known but not host-verified.
-- github_user_id is the numeric GitHub id as text, nullable for a row bound
-- before it was captured.
CREATE TABLE public.user_github_identities (
    user_id uuid NOT NULL,
    github_base_url text NOT NULL,
    login text NOT NULL,
    github_user_id text,
    email text,
    source text NOT NULL,
    verified_at timestamp with time zone,
    -- NULL = the one-shot dashboard history backfill is still owed for this identity.
    dashboard_backfilled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT user_github_identities_source_check CHECK ((source = ANY (ARRAY['pat'::text, 'connect_oauth'::text, 'scim'::text, 'login_claim'::text])))
);


-- Host-scoped Jira identity bindings, the sibling of user_github_identities: the
-- key is (user_id, jira_base_url), matching the per-(user, host) key the Jira PAT
-- is custodied under ("jira_token/<host>"). account_id is the Atlassian StableID
-- (Cloud accountId, else Server/DC key); 'pat' is the only source written today.
CREATE TABLE public.user_jira_identities (
    user_id uuid NOT NULL,
    jira_base_url text NOT NULL,
    account_id text NOT NULL,
    display_name text,
    source text NOT NULL,
    verified_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT user_jira_identities_source_check CHECK ((source = ANY (ARRAY['pat'::text, 'connect_oauth'::text, 'scim'::text, 'cloud_api_token'::text])))
);


