GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.blueprint_runs  TO tf_app;


--
-- Per-org GitHub App registration + installation tracking.
--
-- Orgs on the deployment-default App have NO org_github_apps row. The
-- `_ref` columns hold org_secrets key pointers, so App secrets never live in the
-- relational schema. Installations are 1:N from an org with no pointer back: an
-- org has at most one App registered at a time, so org_id resolves it.

CREATE TABLE public.org_github_apps (
    org_id uuid NOT NULL,
    app_id text NOT NULL,
    slug text NOT NULL,
    client_id text NOT NULL,
    client_secret_ref text NOT NULL,
    pem_ref text NOT NULL,
    webhook_secret_ref text NOT NULL,
    owner_type text DEFAULT 'user'::text NOT NULL,
    registered_at timestamp with time zone DEFAULT now() NOT NULL,
    registered_by_user_id uuid,
    active boolean DEFAULT true NOT NULL,
    -- Numeric GitHub user-account id of the App's bot ("<slug>[bot]"), fetched
    -- best-effort at registration. NOT the App id. NULL = unknown, giving a plain
    -- "<slug>[bot]@..." email; set, it gives the numeric-id noreply form so bot
    -- commits link on github.com.
    bot_user_id bigint
);

ALTER TABLE ONLY public.org_github_apps
    ADD CONSTRAINT org_github_apps_pkey PRIMARY KEY (org_id);

ALTER TABLE ONLY public.org_github_apps
    ADD CONSTRAINT org_github_apps_app_id_key UNIQUE (app_id);

ALTER TABLE ONLY public.org_github_apps
    ADD CONSTRAINT org_github_apps_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.orgs(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.org_github_apps
    ADD CONSTRAINT org_github_apps_registered_by_user_id_fkey FOREIGN KEY (registered_by_user_id) REFERENCES public.users(id) ON DELETE SET NULL;

ALTER TABLE public.org_github_apps ENABLE ROW LEVEL SECURITY;

-- Writes are admin-only. Reads are open to any org member so ResolveCredential()
-- on the app pool can see whether the org has its own App.
CREATE POLICY org_github_apps_select ON public.org_github_apps FOR SELECT TO tf_app
    USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)));

CREATE POLICY org_github_apps_insert ON public.org_github_apps FOR INSERT TO tf_app
    WITH CHECK (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id)));

CREATE POLICY org_github_apps_update ON public.org_github_apps FOR UPDATE TO tf_app
    USING (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id)))
    WITH CHECK (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id)));

CREATE POLICY org_github_apps_delete ON public.org_github_apps FOR DELETE TO tf_app
    USING (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id)));


-- installation_id is unique only within one GitHub host, and per-org GHES bases
-- mean two orgs' numeric ids can overlap, so the PK is composite and github_host
-- records which GitHub the row came from. account_id is GitHub's numeric id for
-- the installed-on account, stored as text; it survives a rename, so credential
-- resolution matches on it while account_login is what the UI renders. Nullable:
-- an older row resolves by login until a reconcile or webhook fills it in.
CREATE TABLE public.org_github_app_installations (
    installation_id text NOT NULL,
    org_id uuid NOT NULL,
    account_type text NOT NULL,
    account_id text,
    account_login text NOT NULL,
    -- The GitHub deployment this installation lives on, normalized like every
    -- other host key here (EffectiveGitHubHost): trailing slashes trimmed, an
    -- unconfigured base URL resolving to https://github.com, and any path
    -- component KEPT so a GHES mount path keys the same host as its identity rows.
    github_host text DEFAULT 'https://github.com'::text NOT NULL,
    installed_at timestamp with time zone DEFAULT now() NOT NULL,
    removed_at timestamp with time zone,
    -- An account owner can suspend an installation without uninstalling it: the
    -- grant stays, every token minted from it is refused. Suspended iff
    -- suspended_at is non-NULL; suspended_by is the suspending login (display
    -- only). Retained on removal; a re-install clears them with removed_at.
    suspended_at timestamp with time zone,
    suspended_by text,
    -- Whether the grant covers every repository on the account or an enumerated
    -- selection, as GitHub reports it. It says whether drift is possible at all:
    -- an 'all' installation reaches everything the account owns. NULL means not
    -- learned yet, never "no selection" — hence the CHECK admitting NULL.
    repository_selection text,
    CONSTRAINT org_github_app_installations_account_type_check
        CHECK ((account_type = ANY (ARRAY['Organization'::text, 'User'::text]))),
    CONSTRAINT org_github_app_installations_github_host_check
        CHECK ((github_host <> ''::text)),
    CONSTRAINT org_github_app_installations_repository_selection_check
        CHECK ((repository_selection IS NULL
                OR repository_selection = ANY (ARRAY['all'::text, 'selected'::text])))
);

ALTER TABLE ONLY public.org_github_app_installations
    ADD CONSTRAINT org_github_app_installations_pkey PRIMARY KEY (org_id, installation_id);

ALTER TABLE ONLY public.org_github_app_installations
    ADD CONSTRAINT org_github_app_installations_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.orgs(id) ON DELETE CASCADE;

-- At most one active install per account, without overwriting history: an
-- uninstall stamps removed_at, a reinstall inserts a fresh installation_id.
CREATE UNIQUE INDEX org_github_app_installations_active_account_key
    ON public.org_github_app_installations (org_id, account_login)
    WHERE (removed_at IS NULL);

-- An installation belongs to exactly one workspace per GitHub deployment. The
-- grant is not divisible, `installation.deleted` fires once, the rate budget is
-- shared, and the account owner cannot enumerate who rides their installation.
--
-- With a deployment-level App — one key serving many workspaces — a single
-- listing reports every tenant's installations, so nothing about the credential
-- keeps one workspace from claiming another's. This index is the backstop under
-- the reconcile scoping that keeps a managed workspace's refresh to what it has
-- already bound: the filter is the correctness, this is what holds when a claim
-- path forgets the bind's per-installation lock. An advisory lock is not a
-- substitute for either — it orders writes, it does not validate them.
--
-- github_host is in the key because GitHub numbers installations per deployment
-- and not universally: a self-host aggregating orgs across two GHES instances
-- legitimately holds id 456 twice, meaning two unrelated installations. Partial
-- on removed_at IS NULL like the index above — an uninstalled installation
-- reaches nothing and holds nothing, so re-binding that id elsewhere is an
-- ordinary bind rather than a collision.
CREATE UNIQUE INDEX org_github_app_installations_active_host_installation_key
    ON public.org_github_app_installations (github_host, installation_id)
    WHERE (removed_at IS NULL);

CREATE INDEX org_github_app_installations_org_idx
    ON public.org_github_app_installations (org_id);

ALTER TABLE public.org_github_app_installations ENABLE ROW LEVEL SECURITY;

-- Installation rows mirror GitHub-side state, written only by the webhook handler
-- on the admin pool. App-pool members read but never write.
CREATE POLICY org_github_app_installations_select ON public.org_github_app_installations FOR SELECT TO tf_app
    USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)));

CREATE POLICY org_github_app_installations_insert ON public.org_github_app_installations FOR INSERT TO tf_app
    WITH CHECK (false);

CREATE POLICY org_github_app_installations_update ON public.org_github_app_installations FOR UPDATE TO tf_app
    USING (false);

CREATE POLICY org_github_app_installations_delete ON public.org_github_app_installations FOR DELETE TO tf_app
    USING (false);

