GRANT ALL ON TABLE public.org_github_apps TO anon;
GRANT ALL ON TABLE public.org_github_apps TO authenticated;
GRANT ALL ON TABLE public.org_github_apps TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.org_github_apps TO tf_app;

GRANT ALL ON TABLE public.org_github_app_installations TO postgres;
GRANT ALL ON TABLE public.org_github_app_installations TO anon;
GRANT ALL ON TABLE public.org_github_app_installations TO authenticated;
GRANT ALL ON TABLE public.org_github_app_installations TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.org_github_app_installations TO tf_app;


-- The reachable-repo cache: one mirror of "which repositories can this org
-- reach", populated by every credential class and read by the repository
-- picker, the team-repos write gate, and the two App-tier findings below.
--
-- It is a cache of an external fact, rebuilt in full per refresh, with no durable
-- identity — unlike `repositories`, the registry of TF entities that worktrees,
-- entities, clone state and a hand-set base_branch hang off. It contains
-- repositories nobody tracks, so it is neither a registry row nor a column on
-- repositories.
--
--   * reach without purpose — the App can reach a repository no team tracks;
--   * scope drift — a team tracks a repository outside the grant, which makes
--     that repository silently unpollable.
--
-- Both findings are statements about a GRANT, which is why neither reads the
-- 'pat' rows: a PAT's reach is the account's, not something TF was granted. That
-- exclusion is structural and permanent. The queries also match 'byo_app' alone
-- among the two App classes, and that one is neither: a managed workspace's
-- reach is a grant on the same terms, and what it waits on is the surface that
-- renders these findings. The store interface carries that deferral where the
-- queries live — this table stores every class the CHECKs below admit, and takes
-- no view on which of them a reader asks about.
CREATE TABLE public.reachable_repositories (
    org_id uuid NOT NULL,
    -- Which credential system observed this reach. Part of the key because an org
    -- that switches tiers has both answers on file for a moment; every read
    -- filters on the org's CURRENT class, so the other tier's rows are inert.
    credential_class text NOT NULL
        CONSTRAINT reachable_repositories_class_check
        CHECK (credential_class IN ('pat', 'byo_app', 'managed_app')),
    -- The credential INSTANCE the reach was observed through — the scope one
    -- refresh replaces atomically. Both App classes hang off the installation
    -- row, which records its GitHub deployment and cascades on uninstall; the
    -- PAT tier has none, so it carries the host directly.
    installation_id text,
    host text,
    -- The issuing provider, carried so the registry join is written against the
    -- registry's own key (org_id, source, lower(owner), lower(repo)). Not part of
    -- this table's key: every row here is reached through a GitHub credential.
    source text DEFAULT 'github'::text NOT NULL,
    owner text NOT NULL,
    repo text NOT NULL,
    -- The provider's own repository id, so a cache entry and a registry row match
    -- by id when slugs disagree mid-rename. NULL rows are matched by slug.
    external_id text,
    -- The picker's display fields, mirrored because the picker is served from here
    -- rather than proxied. Empty string rather than NULL: display strings with no
    -- meaningful absent state.
    description text DEFAULT ''::text NOT NULL,
    language text DEFAULT ''::text NOT NULL,
    html_url text DEFAULT ''::text NOT NULL,
    -- GitHub's own timestamp string, stored verbatim and passed through to the
    -- client; never compared, sorted on, or parsed here.
    pushed_at text DEFAULT ''::text NOT NULL,
    private boolean DEFAULT false NOT NULL,
    -- When the refresh that wrote this row ran: a staleness gate for the
    -- re-enumeration TTL and the write gate choosing cache over upstream probe.
    observed_at timestamp with time zone DEFAULT now() NOT NULL,
    -- Exactly one scope column per class: with both, a row has two answers to
    -- what one refresh replaces; with neither, it can never be replaced.
    CONSTRAINT reachable_repositories_scope_check
        CHECK ((credential_class IN ('byo_app', 'managed_app') AND installation_id IS NOT NULL AND host IS NULL)
            OR (credential_class = 'pat' AND installation_id IS NULL AND host IS NOT NULL))
);

ALTER TABLE ONLY public.reachable_repositories
    ADD CONSTRAINT reachable_repositories_installation_fkey
    FOREIGN KEY (org_id, installation_id)
    REFERENCES public.org_github_app_installations (org_id, installation_id) ON DELETE CASCADE;

-- The natural key per scope shape, case-folded like repositories_identity:
-- GitHub identifiers are case-insensitive, so a case-sensitive index behind a
-- case-insensitive guard admits duplicates when two writers race. Two partial
-- indexes, not one over coalesce(installation_id, host), which would collide.
--
-- Both App classes share the App predicate rather than taking an index each:
-- the key already contains installation_id, an installation belongs to exactly
-- one App, and an org holds one class at a time, so a cross-class collision on
-- the same installation id is not constructible. A class outside both
-- predicates would carry no uniqueness constraint at all, and the writer's
-- ON CONFLICT DO NOTHING would have no conflict to detect.
CREATE UNIQUE INDEX reachable_repositories_app_identity
    ON public.reachable_repositories USING btree (org_id, installation_id, lower(owner), lower(repo))
    WHERE credential_class IN ('byo_app', 'managed_app');

CREATE UNIQUE INDEX reachable_repositories_pat_identity
    ON public.reachable_repositories USING btree (org_id, host, lower(owner), lower(repo))
    WHERE credential_class = 'pat';

-- The registry join and the drift queries over it. Same shape as
-- repositories_identity, so either side can drive the join.
CREATE INDEX reachable_repositories_registry_join
    ON public.reachable_repositories USING btree (org_id, source, lower(owner), lower(repo));

-- The picker's own read: one org's current class, ordered by folded slug —
-- offset paging over an unordered set drops and repeats rows.
CREATE INDEX reachable_repositories_picker
    ON public.reachable_repositories USING btree (org_id, credential_class, lower(owner), lower(repo));

ALTER TABLE public.reachable_repositories ENABLE ROW LEVEL SECURITY;

-- The cache is GitHub-side state written only by the refresh on the admin pool;
-- app-pool members read and never write. Force-refresh is process control.
CREATE POLICY reachable_repositories_select ON public.reachable_repositories FOR SELECT TO tf_app
    USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)));

CREATE POLICY reachable_repositories_insert ON public.reachable_repositories FOR INSERT TO tf_app
    WITH CHECK (false);

CREATE POLICY reachable_repositories_update ON public.reachable_repositories FOR UPDATE TO tf_app
    USING (false);

CREATE POLICY reachable_repositories_delete ON public.reachable_repositories FOR DELETE TO tf_app
    USING (false);

GRANT ALL ON TABLE public.reachable_repositories TO postgres;
GRANT ALL ON TABLE public.reachable_repositories TO anon;
GRANT ALL ON TABLE public.reachable_repositories TO authenticated;
GRANT ALL ON TABLE public.reachable_repositories TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.reachable_repositories TO tf_app;


-- One row per refresh scope, so "we have not looked yet" is representable: a
-- scope that legitimately reaches nothing writes zero repository rows, which
-- row count alone cannot distinguish from an un-run refresh. No FK — scope
-- holds an installation id for byo_app and a host for pat, so there is no
-- single parent. App-pool members read; every app-pool write is denied.
CREATE TABLE public.reachable_scopes (
    org_id uuid NOT NULL,
    credential_class text NOT NULL
        CONSTRAINT reachable_scopes_class_check
        CHECK (credential_class IN ('pat', 'byo_app', 'managed_app')),
    -- The credential instance one refresh replaces: the installation id for the
    -- App classes, the host for pat. Opaque text, never joined on.
    scope text NOT NULL,
    refreshed_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE ONLY public.reachable_scopes
    ADD CONSTRAINT reachable_scopes_pkey PRIMARY KEY (org_id, credential_class, scope);

ALTER TABLE public.reachable_scopes ENABLE ROW LEVEL SECURITY;

CREATE POLICY reachable_scopes_select ON public.reachable_scopes FOR SELECT TO tf_app
    USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)));

CREATE POLICY reachable_scopes_insert ON public.reachable_scopes FOR INSERT TO tf_app
    WITH CHECK (false);

CREATE POLICY reachable_scopes_update ON public.reachable_scopes FOR UPDATE TO tf_app
    USING (false);

CREATE POLICY reachable_scopes_delete ON public.reachable_scopes FOR DELETE TO tf_app
    USING (false);

GRANT ALL ON TABLE public.reachable_scopes TO postgres;
GRANT ALL ON TABLE public.reachable_scopes TO anon;
GRANT ALL ON TABLE public.reachable_scopes TO authenticated;
GRANT ALL ON TABLE public.reachable_scopes TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.reachable_scopes TO tf_app;


-- GitHub webhook delivery dedup. GitHub redelivers on demand (the Redeliver
-- button, 30-day window), so a redelivered copy must not re-run the
-- installation upsert or re-publish to the bus. Keyed (installation_id,
-- delivery_id): a shared-App receiver routes installation.id -> org_id and does
-- not know the tenant at write time. A delivery carrying no installation object
-- stores '' rather than NULL, which a primary key rejects. Rows are pruned
-- after 72h. Admin-pool-only: RLS enabled with no policy (deny-by-default) plus
-- REVOKE ALL from PUBLIC and the app roles; the receiver is pre-auth.
CREATE TABLE public.github_webhook_deliveries (
    installation_id text NOT NULL,
    delivery_id     text NOT NULL,
    received_at     timestamp with time zone NOT NULL DEFAULT now()
);

ALTER TABLE ONLY public.github_webhook_deliveries
    ADD CONSTRAINT github_webhook_deliveries_pkey PRIMARY KEY (installation_id, delivery_id);

-- Serves the prune, the only query that doesn't go through the primary key.
CREATE INDEX github_webhook_deliveries_received_at_idx
    ON public.github_webhook_deliveries (received_at);

ALTER TABLE public.github_webhook_deliveries ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.github_webhook_deliveries FROM PUBLIC;
REVOKE ALL ON public.github_webhook_deliveries FROM anon, authenticated, service_role;


-- The pending-bind record: one row per initiated deployment-App bind ceremony.
--
-- When one App key serves many workspaces, the org<->installation mapping has
-- no source. GitHub's post-install redirect cannot be that source — it is an
-- unsigned GET whose installation_id is sequential, and GitHub's own
-- documentation says not to rely on it — so TF asserts the mapping itself, and
-- this row plus a cookie is what proves the assertion belongs to the workspace
-- that asked for it. The threat it stops is planting: an attacker completes an
-- install themselves, then induces a signed-in TF admin to load our callback
-- with their code and installation id, putting the attacker's repositories into
-- the victim's workspace.
--
-- Durable rather than in-process because the pod that serves the Connect click
-- need not be the pod that serves the callback. An in-memory map would work in
-- development and fail intermittently under load.
--
-- nonce_hash is the SHA-256 of the nonce in lowercase hex; the plaintext lives
-- only in the browser's cookie, so reading this table yields nothing that can
-- complete a bind. It is the primary key because it is also the lookup: the
-- callback knows the nonce and nothing else, which is why the org and the
-- initiating user are columns here rather than parameters the callback could
-- supply for itself.
--
-- user_id is a soft reference with no foreign key: the callback compares it
-- against the returning session's own subject, so an id naming nobody can only
-- fail the comparison — it is never dereferenced, and a cascade would buy
-- nothing a fifteen-minute expiry does not.
--
-- Admin-pool-only, and forced rather than chosen: the consume reads the row BY
-- ITS NONCE HASH and learns the org from it, so the org an RLS policy would
-- gate on is the read's output, not an input. The nonce is the authorization,
-- exactly as an invite token is on the redeem path; the org-admin check that
-- authorizes the create lives in the handler, which is the only place it can.
-- RLS enabled with no policy (deny-by-default) plus REVOKE ALL from PUBLIC and
-- the app roles.
CREATE TABLE public.github_pending_binds (
    nonce_hash    text PRIMARY KEY,
    org_id        uuid NOT NULL REFERENCES public.orgs(id) ON DELETE CASCADE,
    user_id       uuid NOT NULL,
    -- The GitHub login the admin named when connecting an account that already
    -- has the App installed; '' for a ceremony that goes through GitHub's
    -- install page. Carried here and nowhere else, so it never rides a URL.
    account_login text NOT NULL DEFAULT '',
    created_at    timestamptz NOT NULL,
    expires_at  timestamptz NOT NULL,
    consumed_at timestamptz
);

-- Serves the prune, the only query that doesn't go through the primary key.
CREATE INDEX github_pending_binds_expires_at_idx
    ON public.github_pending_binds (expires_at);

ALTER TABLE public.github_pending_binds ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.github_pending_binds FROM PUBLIC;
REVOKE ALL ON public.github_pending_binds FROM anon, authenticated, service_role;


--
-- Durable router event queue (transactional outbox). The in-memory bus drops
-- events for slow subscribers under burst; the router drains this instead. The
-- events audit row and the queue row are written atomically at ingest, and
-- ClaimNext uses FOR UPDATE SKIP LOCKED so workers drain concurrently. Delivery
-- is at-least-once: a crashed 'processing' row is reset to pending at boot and
-- replayed, so router processing is idempotent. Admin-pool wired with org_id
-- bound per statement; the RLS policy below is defense-in-depth.
--
CREATE TABLE public.event_queue (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    org_id       uuid NOT NULL,
    event_id     uuid NOT NULL,
    entity_id    uuid,
    event_type   text NOT NULL,
    status       text NOT NULL DEFAULT 'pending',
    attempts     integer NOT NULL DEFAULT 0,
    last_error   text,
    enqueued_at  timestamp with time zone NOT NULL DEFAULT now(),
    claimed_at   timestamp with time zone,
    processed_at timestamp with time zone,
    -- Stamped atomically at claim (pending -> processing) so ResetProcessing
    -- sweeps only this instance's orphaned rows (executor_id = self AND
    -- boot_epoch < the current epoch), never a live sibling's.
    executor_id  text,
    boot_epoch   bigint,
    -- W3C trace context of the enqueuer, linking routing back to the poll cycle
    -- that emitted the event; only the queue row carries one. NULL is normal
    -- (tracing off, untraced path, no exporter) and routes identically. The
    -- consumer links to this context rather than descending from it.
    traceparent  text
);

ALTER TABLE ONLY public.event_queue
    ADD CONSTRAINT event_queue_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.orgs(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.event_queue
    ADD CONSTRAINT event_queue_event_id_org_id_fkey FOREIGN KEY (event_id, org_id) REFERENCES public.events(id, org_id) ON DELETE CASCADE;
ALTER TABLE ONLY public.event_queue
    ADD CONSTRAINT event_queue_entity_id_org_id_fkey FOREIGN KEY (entity_id, org_id) REFERENCES public.entities(id, org_id) ON DELETE CASCADE;

CREATE INDEX idx_event_queue_pending ON public.event_queue USING btree (id) WHERE (status = 'pending'::text);
CREATE INDEX idx_event_queue_entity ON public.event_queue USING btree (entity_id);
CREATE INDEX idx_event_queue_status_processed ON public.event_queue USING btree (status, processed_at);
CREATE UNIQUE INDEX idx_event_queue_event ON public.event_queue USING btree (event_id);

ALTER TABLE public.event_queue ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_queue_all ON public.event_queue
    USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)))
    WITH CHECK (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)));

GRANT ALL ON TABLE public.event_queue TO postgres;
GRANT ALL ON TABLE public.event_queue TO anon;
GRANT ALL ON TABLE public.event_queue TO authenticated;
GRANT ALL ON TABLE public.event_queue TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.event_queue TO tf_app;


-- Per-org Atlassian OAuth (3LO) app registration for the per-user "Connect
-- Jira" flow; an org with no row falls back to the deployment app.
-- client_secret_ref is an org_secrets key pointer, written via SecretStore.

CREATE TABLE public.org_jira_apps (
    org_id uuid NOT NULL,
    client_id text NOT NULL,
    client_secret_ref text NOT NULL,
    registered_at timestamp with time zone DEFAULT now() NOT NULL,
    registered_by_user_id uuid
);

ALTER TABLE ONLY public.org_jira_apps
    ADD CONSTRAINT org_jira_apps_pkey PRIMARY KEY (org_id);

ALTER TABLE ONLY public.org_jira_apps
    ADD CONSTRAINT org_jira_apps_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.orgs(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.org_jira_apps
    ADD CONSTRAINT org_jira_apps_registered_by_user_id_fkey FOREIGN KEY (registered_by_user_id) REFERENCES public.users(id) ON DELETE SET NULL;

ALTER TABLE public.org_jira_apps ENABLE ROW LEVEL SECURITY;

-- Writes are org-admin-only; reads open to any org member so the app-pool
-- OAuth-app resolver can see whether the org has its own app.
CREATE POLICY org_jira_apps_select ON public.org_jira_apps FOR SELECT TO tf_app
    USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)));

CREATE POLICY org_jira_apps_insert ON public.org_jira_apps FOR INSERT TO tf_app
    WITH CHECK (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id)));

CREATE POLICY org_jira_apps_update ON public.org_jira_apps FOR UPDATE TO tf_app
    USING (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id)))
    WITH CHECK (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id)));

CREATE POLICY org_jira_apps_delete ON public.org_jira_apps FOR DELETE TO tf_app
    USING (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id)));

GRANT ALL ON TABLE public.org_jira_apps TO postgres;
GRANT ALL ON TABLE public.org_jira_apps TO anon;
GRANT ALL ON TABLE public.org_jira_apps TO authenticated;
GRANT ALL ON TABLE public.org_jira_apps TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.org_jira_apps TO tf_app;


--
-- Secrets are encrypted app-side (AES-256-GCM) with TF_SECRET_ENCRYPTION_KEY
-- from .env rather than in Postgres, whose root key would live in the container
-- filesystem and be regenerated by a container recreate. A dump yields only
-- ciphertext.
--

CREATE TABLE public.org_secrets (
    -- Surrogate PK: the natural key (org_id, COALESCE(user_id, …), key) is an
    -- expression over a nullable column. The unique index below is the dedup.
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id      uuid NOT NULL REFERENCES public.orgs(id) ON DELETE CASCADE,
    -- NULL for org-scope secrets; the owning user's id for per-user secrets.
    user_id     uuid NULL REFERENCES public.users(id) ON DELETE CASCADE,
    key         text NOT NULL,
    -- AES-256-GCM ciphertext and its 12-byte nonce (internal/aead).
    ciphertext  bytea NOT NULL,
    nonce       bytea NOT NULL,
    description text NOT NULL DEFAULT '',
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    -- Defense-in-depth: AES-256-GCM uses a 12-byte nonce and a 16-byte auth
    -- tag, so corruption trips at write time, not as a later decrypt failure.
    CONSTRAINT org_secrets_key_nonempty CHECK (key <> ''),
    CONSTRAINT org_secrets_nonce_len CHECK (octet_length(nonce) = 12),
    CONSTRAINT org_secrets_ciphertext_len CHECK (octet_length(ciphertext) >= 16)
);

-- At most one row per (scope, key); a NULL user_id collapses to the all-zero
-- sentinel UUID so org and per-user rows can't collide. The UPSERTs target it.
CREATE UNIQUE INDEX org_secrets_scope_key_uniq
    ON public.org_secrets (
        org_id,
        COALESCE(user_id, '00000000-0000-0000-0000-000000000000'::uuid),
        key
    );

ALTER TABLE public.org_secrets ENABLE ROW LEVEL SECURITY;

-- Two permissive policies, OR'd: (org-scope row AND org matches) OR (own
-- user-scope row AND org matches). The admin pool bypasses RLS for *System.

CREATE POLICY org_secrets_org ON public.org_secrets
    FOR ALL
    TO tf_app
    USING (user_id IS NULL AND org_id = tf.current_org_id())
    WITH CHECK (user_id IS NULL AND org_id = tf.current_org_id());

-- Per-user rows: gate on org AND user — a session as user A can't see B's.
CREATE POLICY org_secrets_user ON public.org_secrets
    FOR ALL
    TO tf_app
    USING (user_id = tf.current_user_id() AND org_id = tf.current_org_id())
    WITH CHECK (user_id = tf.current_user_id() AND org_id = tf.current_org_id());

-- Default privileges auto-grant public-schema tables to anon/authenticated/
-- service_role at CREATE; strip them so only tf_app and the admin pool reach it.
REVOKE ALL ON public.org_secrets FROM PUBLIC;
REVOKE ALL ON public.org_secrets FROM anon, authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.org_secrets TO tf_app;


-- TF-owned, link-based org invites: an admin creates one (email + role +
-- optional target team) and gets a one-time accept_url; the recipient
-- authenticates and redeems the raw token, minting their org_memberships row.
-- The raw token is NEVER stored — only sha256(token) in token_hash. Postgres
-- only: local mode never mounts the invite routes, so there is no SQLite twin.

CREATE TABLE public.org_invites (
    id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id         uuid NOT NULL REFERENCES public.orgs(id)  ON DELETE CASCADE,
    email          text NOT NULL,               -- stored lower-cased (app normalizes)
    role           public.org_role NOT NULL DEFAULT 'member',
    target_team_id uuid NULL,                   -- NULL = org-only; composite FK below pins it to org_id
    token_hash     bytea NOT NULL,              -- sha256(raw token); raw token is NEVER stored
    invited_by     uuid NULL REFERENCES public.users(id) ON DELETE SET NULL, -- audit only
    expires_at     timestamptz NOT NULL,
    accepted_at    timestamptz NULL,
    accepted_by    uuid NULL REFERENCES public.users(id) ON DELETE SET NULL, -- who redeemed (audit)
    revoked_at     timestamptz NULL,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT org_invites_email_nonempty CHECK (email <> ''),
    -- 'owner' is the orgs.owner_user_id sentinel, never granted via invite.
    CONSTRAINT org_invites_role_not_owner CHECK (role <> 'owner'),
    -- Tenant-scoped FK: a non-NULL target_team_id must belong to this invite's
    -- own org. The redeem path runs on the admin pool (BYPASSRLS), so this is
    -- the only cross-org guard. MATCH SIMPLE skips org-only invites.
    CONSTRAINT org_invites_target_team_fkey
        FOREIGN KEY (target_team_id, org_id) REFERENCES public.teams (id, org_id)
        ON DELETE SET NULL (target_team_id)
);

CREATE UNIQUE INDEX org_invites_token_hash_uniq ON public.org_invites (token_hash);

-- At most ONE active (un-accepted, un-revoked) invite per (org, email);
-- re-inviting an accepted or revoked address is allowed.
CREATE UNIQUE INDEX org_invites_active_uniq
    ON public.org_invites (org_id, lower(email))
    WHERE accepted_at IS NULL AND revoked_at IS NULL;

CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.org_invites
    FOR EACH ROW EXECUTE FUNCTION tf.set_updated_at();

ALTER TABLE public.org_invites ENABLE ROW LEVEL SECURITY;

-- Create/list/revoke are org-admin-gated. The redeem surface is not
-- expressible in RLS — the actor is an outsider holding a token — so it runs
-- on the admin pool, with the token itself as the authorization.
CREATE POLICY org_invites_select ON public.org_invites FOR SELECT
  USING ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

CREATE POLICY org_invites_insert ON public.org_invites FOR INSERT
  WITH CHECK ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

CREATE POLICY org_invites_update ON public.org_invites FOR UPDATE
  USING ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id))
  WITH CHECK ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

-- Strip the auto-granted public-schema privileges so the table is reachable
-- only by tf_app (under RLS) and the admin pool (for the redeem paths).
REVOKE ALL ON public.org_invites FROM PUBLIC;
REVOKE ALL ON public.org_invites FROM anon, authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.org_invites TO tf_app;


-- TF-owned SSO binding tables, multi-org throughout:
--
--   - sso_connections — an org↔IdP-provider binding (SAML today, OIDC later).
--     provider_id is the ONE bridge to GoTrue (its sso_providers.id); TF owns
--     the org + default role, GoTrue owns authN.
--   - sso_domains — verified email domains routing an identifier-first login
--     (email → connection) via DNS-TXT verification. A verified domain belongs
--     to at most one org deployment-wide; pending claims are non-exclusive.
--
-- Postgres only: the SQLite store impls are stubs returning
-- ErrNotApplicableInLocal.

CREATE TABLE public.sso_connections (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id       uuid NOT NULL REFERENCES public.orgs(id) ON DELETE CASCADE,
    kind         text NOT NULL DEFAULT 'saml',
    -- GoTrue sso_providers.id, stored as opaque text: no FK into GoTrue's
    -- schema. Globally unique (index below) so one provider maps to one org.
    provider_id  text NOT NULL,
    -- Role JIT provisioning grants a first-time SSO user; promotion is manual.
    -- 'owner' is the orgs.owner_user_id sentinel, never granted via SSO.
    default_role public.org_role NOT NULL DEFAULT 'member',
    enabled      boolean NOT NULL DEFAULT true,
    -- When true, a login via a non-SSO identity whose verified email is on one
    -- of this connection's verified domains is rejected unless the principal is
    -- break-glass. A separate axis from enabled. The handler gates the toggle
    -- on a proven-working connection (enabled + verified domain + passed Test).
    enforced     boolean NOT NULL DEFAULT false,
    -- Stamped when a Test passes end-to-end (NULL = never); enforcement gates on it.
    last_tested_at timestamptz NULL,
    -- Which identity-provider product sits behind the connection, so a login
    -- through it can wear the vendor's mark and the admin surface can name it.
    -- Derived from the metadata URL's host at registration and overridable by
    -- an org admin; NULL is "not known", which renders as plain SSO.
    idp          text NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT sso_connections_kind_chk       CHECK (kind IN ('saml','oidc')),
    CONSTRAINT sso_connections_role_not_owner CHECK (default_role <> 'owner'),
    CONSTRAINT sso_connections_idp_chk        CHECK (idp IN ('entra','okta','google','onelogin','ping','other'))
);

-- One org per GoTrue provider, deployment-wide: provider_id → org is a function.
CREATE UNIQUE INDEX sso_connections_provider_uniq ON public.sso_connections (provider_id);

-- (id, org_id) is trivially unique, declared so sso_domains can FK the pair:
-- RLS gates the org_id column, only this FK pins connection_id to the same org.
ALTER TABLE public.sso_connections ADD CONSTRAINT sso_connections_id_org_id_key UNIQUE (id, org_id);

CREATE TABLE public.sso_domains (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    -- Lead column of the composite FK below, which ties (connection_id, org_id)
    -- to the parent's (id, org_id); no standalone FK.
    connection_id uuid NOT NULL,
    -- Denormalized from the parent so RLS gates on org_id without a join. RLS
    -- pins this column to the writer's own org, but would not stop a self-org
    -- row from pointing connection_id at another org's connection; the
    -- composite FK below closes that on every write path, admin-pool included.
    org_id        uuid NOT NULL REFERENCES public.orgs(id) ON DELETE CASCADE,
    domain        text NOT NULL,
    -- DNS-TXT verification token (_triagefactory-verification.<domain>).
    -- Published publicly: it proves control of the zone, it is not a secret.
    token         text NOT NULL,
    -- NULL until the DNS-TXT check passes; a pending row does not route and
    -- does not reserve the domain.
    verified_at   timestamptz NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT sso_domains_domain_nonempty CHECK (domain <> ''),
    -- NOT NULL alone permits '', which would yield an empty DNS-TXT challenge.
    CONSTRAINT sso_domains_token_nonempty CHECK (token <> ''),
    -- Tenant-scoped composite FK: a domain's (connection_id, org_id) must match
    -- a real sso_connections (id, org_id), forcing connection_id into the same
    -- org. ON DELETE CASCADE retires a connection's domains with it.
    CONSTRAINT sso_domains_connection_fkey
        FOREIGN KEY (connection_id, org_id) REFERENCES public.sso_connections (id, org_id)
        ON DELETE CASCADE
);

-- One claim per (org, domain). Case-insensitive because domains are.
CREATE UNIQUE INDEX sso_domains_org_domain_uniq ON public.sso_domains (org_id, lower(domain));

-- The isolation guarantee: a verified domain belongs to at most one org
-- deployment-wide. Pending claims are non-exclusive; first-to-verify wins and
-- the loser's set-verified trips this index. It holds regardless of RLS, and
-- handlers map the collision to "domain already claimed" without naming who.
CREATE UNIQUE INDEX sso_domains_verified_global_uniq
    ON public.sso_domains (lower(domain)) WHERE verified_at IS NOT NULL;

-- Postgres doesn't auto-index a referencing column, and the ON DELETE CASCADE
-- must find a connection's domains without a seq scan (org_domain leads org_id).
CREATE INDEX sso_domains_connection_idx ON public.sso_domains (connection_id);

CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.sso_connections
    FOR EACH ROW EXECUTE FUNCTION tf.set_updated_at();
CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.sso_domains
    FOR EACH ROW EXECUTE FUNCTION tf.set_updated_at();

ALTER TABLE public.sso_connections ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sso_domains ENABLE ROW LEVEL SECURITY;

-- Connection CRUD and domain claim/verify are org-admin-gated, SELECT included.
-- DELETE needs its own policy: both stores expose a delete primitive that runs
-- on the app pool. The two login-time reads (GetByProviderID,
-- GetVerifiedByDomain) cross the tenant boundary — the actor has no membership
-- yet — so they run on the admin pool, authorized by the lookup key itself.

CREATE POLICY sso_connections_select ON public.sso_connections FOR SELECT
  USING ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

CREATE POLICY sso_connections_insert ON public.sso_connections FOR INSERT
  WITH CHECK ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

CREATE POLICY sso_connections_update ON public.sso_connections FOR UPDATE
  USING ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id))
  WITH CHECK ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

CREATE POLICY sso_connections_delete ON public.sso_connections FOR DELETE
  USING ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

CREATE POLICY sso_domains_select ON public.sso_domains FOR SELECT
  USING ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

CREATE POLICY sso_domains_insert ON public.sso_domains FOR INSERT
  WITH CHECK ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

CREATE POLICY sso_domains_update ON public.sso_domains FOR UPDATE
  USING ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id))
  WITH CHECK ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

CREATE POLICY sso_domains_delete ON public.sso_domains FOR DELETE
  USING ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

-- Strip the auto-granted public-schema privileges so each table is reachable
-- only by tf_app (under RLS) and the admin pool (for the login-time reads).
REVOKE ALL ON public.sso_connections FROM PUBLIC;
REVOKE ALL ON public.sso_connections FROM anon, authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.sso_connections TO tf_app;

REVOKE ALL ON public.sso_domains FROM PUBLIC;
REVOKE ALL ON public.sso_domains FROM anon, authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.sso_domains TO tf_app;


-- Principals that may still authenticate via their non-SSO (GitHub) identity
-- under SSO enforcement — the recovery path if the IdP breaks. The handler
-- refuses to remove the last row while a connection is enforced. FK to orgs +
-- users, not org_memberships, so a membership change never cascade-drops a
-- break-glass row out from under that guard.
CREATE TABLE public.sso_break_glass (
    org_id     uuid NOT NULL REFERENCES public.orgs(id)  ON DELETE CASCADE,
    user_id    uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (org_id, user_id)
);

-- Serves by-principal reads and the users-side ON DELETE CASCADE.
CREATE INDEX sso_break_glass_user_idx ON public.sso_break_glass (user_id);

ALTER TABLE public.sso_break_glass ENABLE ROW LEVEL SECURITY;

-- Org-admin-gated. The login-time IsBreakGlass read has no membership claims
-- for the target org, so it runs on the admin pool with the resolved (org_id,
-- principal) as the authorization.
CREATE POLICY sso_break_glass_select ON public.sso_break_glass FOR SELECT
  USING ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

CREATE POLICY sso_break_glass_insert ON public.sso_break_glass FOR INSERT
  WITH CHECK ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

CREATE POLICY sso_break_glass_delete ON public.sso_break_glass FOR DELETE
  USING ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

REVOKE ALL ON public.sso_break_glass FROM PUBLIC;
REVOKE ALL ON public.sso_break_glass FROM anon, authenticated, service_role;
GRANT SELECT, INSERT, DELETE ON public.sso_break_glass TO tf_app;


-- Principal identity model: public.users is the principal (one row per human)
-- and this table maps each GoTrue auth.users login identity to it. An identity
-- links to an existing principal when its verified email matches, else a new
-- principal is minted; provider_subject holds the IdP's stable subject / SAML
-- NameID so a re-link need not trust email alone. Resolution runs on the admin
-- pool at login with no claims context: no tf_app grant, no policy, RLS enabled
-- as a deny-by-default backstop.

CREATE TABLE public.user_identities (
    auth_user_id uuid NOT NULL,
    user_id uuid NOT NULL,
    provider text NOT NULL,
    provider_subject text,
    -- The GoTrue SSO provider that minted a 'saml' identity (sso_providers.id,
    -- opaque text — the same value sso_connections.provider_id binds to an
    -- org). NULL for github rows, and for saml rows written before the login
    -- path stamped it; every login refreshes it, so those rows heal.
    sso_provider_id text,
    -- The provider's own handle for a 'github' identity (the login claim's
    -- user_name) — how the account surface names the door a person came in
    -- by. Distinct from user_github_identities.login, which is the account
    -- the factory ACTS as and may be a different one. NULL for saml rows and
    -- for github rows from before the stamp; refreshed at every login.
    login text,
    email text,
    email_verified boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT user_identities_provider_check CHECK ((provider = ANY (ARRAY['github'::text, 'saml'::text])))
);

ALTER TABLE ONLY public.user_identities
    ADD CONSTRAINT user_identities_pkey PRIMARY KEY (auth_user_id);

ALTER TABLE ONLY public.user_identities
    ADD CONSTRAINT user_identities_auth_user_id_fkey FOREIGN KEY (auth_user_id) REFERENCES auth.users(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.user_identities
    ADD CONSTRAINT user_identities_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE;

CREATE INDEX user_identities_user_id_idx ON public.user_identities USING btree (user_id);

-- Verified-email auto-link lookup at login: which principal owns this email.
CREATE INDEX user_identities_link_lookup_idx ON public.user_identities USING btree (lower(email)) WHERE email_verified;

CREATE TRIGGER user_identities_set_updated_at BEFORE UPDATE ON public.user_identities FOR EACH ROW EXECUTE FUNCTION tf.set_updated_at();

ALTER TABLE public.user_identities ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.user_identities FROM PUBLIC;
REVOKE ALL ON public.user_identities FROM anon, authenticated, service_role;


-- guard_team_admins: each team must retain at least one 'admin' membership. A
-- write that would leave a team without one raises SQLSTATE 23514, surfaced as
-- db.ErrLastTeamAdminGuard and answered as a 409. SECURITY DEFINER (search_path
-- pinned) so the count reads true team state, not the caller's RLS-filtered view.

-- +goose StatementBegin
CREATE OR REPLACE FUNCTION tf.guard_team_admins() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM affected a
    WHERE NOT EXISTS (
      SELECT 1 FROM memberships
       WHERE team_id = a.team_id AND role = 'admin'
    )
  ) THEN
    RAISE EXCEPTION 'each team must retain at least one admin role'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER memberships_keep_admin_on_delete AFTER DELETE ON public.memberships REFERENCING OLD TABLE AS affected FOR EACH STATEMENT EXECUTE FUNCTION tf.guard_team_admins();

CREATE TRIGGER memberships_keep_admin_on_update AFTER UPDATE ON public.memberships REFERENCING OLD TABLE AS affected FOR EACH STATEMENT EXECUTE FUNCTION tf.guard_team_admins();


-- auth_events: the SOC2 authentication audit log — append-only capture of every
-- authentication / session outcome (login, logout, refresh failure, JWT-verify
-- failure, SSO enforcement, break-glass). Writes are best-effort: a failure is
-- logged and swallowed rather than failing the auth action. event_type is free
-- text (domain.AuthEvent*) with no CHECK; org_id and user_id are nullable
-- because a pre-auth / pre-identity failure has neither. Admin-pool-only system
-- table: writes and reads carry no claims and org_id is often NULL, so RLS is
-- enabled with no policy (deny-by-default) plus REVOKE from the app roles.
-- Never auto-purged.
CREATE TABLE public.auth_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid,
    user_id uuid,
    session_id uuid,
    event_type text NOT NULL,
    ip_address inet,
    user_agent text,
    detail_json jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE ONLY public.auth_events
    ADD CONSTRAINT auth_events_pkey PRIMARY KEY (id);

-- Plain (NO ACTION) FKs: an org or user deletion is blocked while auth_events
-- still reference it, preserving the authentication trail.
ALTER TABLE ONLY public.auth_events
    ADD CONSTRAINT auth_events_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.orgs(id);

ALTER TABLE ONLY public.auth_events
    ADD CONSTRAINT auth_events_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id);

-- SET NULL: the audit row outlives the session reaper's retention window.
ALTER TABLE ONLY public.auth_events
    ADD CONSTRAINT auth_events_session_id_fkey FOREIGN KEY (session_id) REFERENCES public.sessions(id) ON DELETE SET NULL;

-- Partial indexes skip the frequent NULL-org / NULL-user rows.
CREATE INDEX auth_events_org_ts ON public.auth_events USING btree (org_id, created_at DESC) WHERE (org_id IS NOT NULL);
CREATE INDEX auth_events_user_ts ON public.auth_events USING btree (user_id, created_at DESC) WHERE (user_id IS NOT NULL);
CREATE INDEX auth_events_type_ts ON public.auth_events USING btree (event_type, created_at DESC);

ALTER TABLE public.auth_events ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.auth_events FROM PUBLIC;
REVOKE ALL ON public.auth_events FROM anon, authenticated, service_role;


-- seat_claims: the per-seat license ledger — one row per (billing period, user)
-- = one committed seat. The login edge counts distinct claimants for the period
-- and inserts in one transaction serialized by a per-period advisory lock, so
-- concurrent first-logins cannot both slip past the cap; PK (period, user_id) is
-- the idempotency key and count(*) per period is the billable total. No org_id:
-- a seat cap is deployment-wide. Admin-pool-only system table, RLS
-- deny-by-default like auth_events; parity-only under SQLite.
CREATE TABLE public.seat_claims (
    period     text NOT NULL,
    user_id    uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

-- PK doubles as the per-period count index (leftmost-prefix scan on period).
ALTER TABLE ONLY public.seat_claims
    ADD CONSTRAINT seat_claims_pkey PRIMARY KEY (period, user_id);

-- CASCADE: a deleted user frees their held seats; this ledger is transient.
ALTER TABLE ONLY public.seat_claims
    ADD CONSTRAINT seat_claims_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE;

ALTER TABLE public.seat_claims ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.seat_claims FROM PUBLIC;
REVOKE ALL ON public.seat_claims FROM anon, authenticated, service_role;


-- org_slack_workspaces: the (Slack workspace, Slack app) <-> org bind, keyed on
-- Slack's workspace/team ID (their legacy naming, unrelated to TF teams) and the
-- app's api_app_id, which rides every event delivery. A workspace may host many
-- apps; a Slack app belongs to exactly one TF org across every workspace it is
-- installed in. api_app_id is not unique on its own, so no SQL constraint
-- expresses that second rule: the connect handler takes an advisory lock on
-- api_app_id (ee/slack WorkspaceStore.LockApp) and checks for a row under
-- another org in the same transaction. The PK violation is the backstop, mapped
-- to a 409 that never names the owning org.
--
-- transport is inferred at connect from which credentials were supplied; a row
-- may carry both signing_secret_ref and app_token_ref, so the one-ref-per-
-- transport pairing is an ee/slack invariant, not a CHECK. The *_ref columns are
-- org_secrets key names (internal/integrations.SlackWorkspaceKeysFor), never
-- credential values. Postgres-only; the SQLite store is a stub returning
-- ErrNotApplicableInLocal.

CREATE TABLE public.org_slack_workspaces (
    workspace_id text NOT NULL,
    api_app_id text NOT NULL,
    org_id uuid NOT NULL REFERENCES public.orgs(id) ON DELETE CASCADE,
    workspace_name text NOT NULL DEFAULT '',
    enterprise_id text,
    transport text NOT NULL CHECK (transport IN ('socket', 'events_api')),
    bot_user_id text NOT NULL DEFAULT '',
    bot_token_ref text NOT NULL,
    signing_secret_ref text,
    app_token_ref text,
    registered_by_user_id uuid REFERENCES public.users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, api_app_id)
);

-- Serves the per-org list/count reads (ListForOrg) and the org_id FK.
CREATE INDEX org_slack_workspaces_org_idx ON public.org_slack_workspaces (org_id);

CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.org_slack_workspaces
    FOR EACH ROW EXECUTE FUNCTION tf.set_updated_at();

ALTER TABLE public.org_slack_workspaces ENABLE ROW LEVEL SECURITY;

-- SELECT is member-visible (any org member may see what is connected); writes
-- are org-admin-only, since connecting a workspace is a credential gesture.
CREATE POLICY org_slack_workspaces_select ON public.org_slack_workspaces FOR SELECT TO tf_app
  USING ((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id));

CREATE POLICY org_slack_workspaces_insert ON public.org_slack_workspaces FOR INSERT TO tf_app
  WITH CHECK ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

CREATE POLICY org_slack_workspaces_update ON public.org_slack_workspaces FOR UPDATE TO tf_app
  USING ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id))
  WITH CHECK ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

CREATE POLICY org_slack_workspaces_delete ON public.org_slack_workspaces FOR DELETE TO tf_app
  USING ((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id));

-- supabase_admin's default privileges auto-grant new public tables to
-- anon/authenticated/service_role; strip them so only tf_app (under RLS) and the
-- admin pool reach this table.
REVOKE ALL ON public.org_slack_workspaces FROM PUBLIC;
REVOKE ALL ON public.org_slack_workspaces FROM anon, authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.org_slack_workspaces TO tf_app;


-- user_slack_identities: maps the Slack sender who @mentioned the bot to a TF
-- user, for run-visibility grants and audit attribution. Capture only — the
-- sender never affects routing or ownership.
--
-- Keyed (workspace_id, slack_user_id) with a nullable user_id, unlike
-- user_github_identities / user_jira_identities (keyed on user_id) where a user
-- binds their own credential: Slack capture is inbound and system-initiated. A
-- NULL-user row is the negative cache — its last_attempt_at suppresses a repeat
-- users.info call within the resolver's retry TTL. Resolution matches a verified
-- email against public.user_identities; no email is stored here, only the
-- display name audit rendering needs. source is 'auto_email' (today's only
-- writer) or 'oidc' (reserved for Sign-in-with-Slack). The key omits api_app_id
-- so two apps in one workspace share these rows; there is therefore no FK to
-- org_slack_workspaces, and disconnecting the last app leaves identity rows to
-- go stale. Postgres-only; the SQLite store returns ErrNotApplicableInLocal.
CREATE TABLE public.user_slack_identities (
    workspace_id text NOT NULL,
    slack_user_id text NOT NULL,
    user_id uuid REFERENCES public.users(id) ON DELETE CASCADE,
    slack_display_name text,
    source text NOT NULL DEFAULT 'auto_email',
    last_attempt_at timestamptz NOT NULL DEFAULT now(),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, slack_user_id),
    CONSTRAINT user_slack_identities_source_check CHECK (source IN ('auto_email', 'oidc'))
);

-- Reverse lookup: which Slack identities map to this TF user. Partial because a
-- NULL-user negative-cache row is never looked up by user_id.
CREATE INDEX user_slack_identities_user_idx ON public.user_slack_identities (user_id) WHERE user_id IS NOT NULL;

CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.user_slack_identities
    FOR EACH ROW EXECUTE FUNCTION tf.set_updated_at();

ALTER TABLE public.user_slack_identities ENABLE ROW LEVEL SECURITY;

-- Self-only read/write, mirroring user_github_identities_modify. A NULL-user
-- negative-cache row matches no current_user_id(), so it is invisible on the app
-- pool; every resolution write goes through the admin pool's ...System methods.
CREATE POLICY user_slack_identities_modify ON public.user_slack_identities USING ((user_id = tf.current_user_id())) WITH CHECK ((user_id = tf.current_user_id()));

CREATE POLICY user_slack_identities_select ON public.user_slack_identities FOR SELECT USING ((user_id = tf.current_user_id()));

-- Strip supabase_admin's default grants: only tf_app (under RLS) and the admin pool.
REVOKE ALL ON public.user_slack_identities FROM PUBLIC;
REVOKE ALL ON public.user_slack_identities FROM anon, authenticated, service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_slack_identities TO tf_app;


-- slack_event_deliveries: cross-transport delivery dedup. Slack retries
-- deliveries (webhook X-Slack-Retry-Num; Socket Mode redelivers unacked
-- envelopes), and the Events API receiver and the Socket Mode client can only
-- share dedup state through storage. Keyed (api_app_id, event_id): delivery
-- streams are per-app — Slack load-balances an app's envelopes across all of
-- that app's open sockets regardless of workspace — so keying on workspace_id
-- would let two apps sharing a workspace collide on one event_id. Admin-pool-
-- only system table (RLS enabled, no policy, REVOKEd from the app roles): the
-- receiver has no request claims and there is no app-pool caller. No index
-- beyond the PK — volume is low and an opportunistic 72h prune keeps it small.
CREATE TABLE public.slack_event_deliveries (
    api_app_id text NOT NULL,
    event_id text NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (api_app_id, event_id)
);

ALTER TABLE public.slack_event_deliveries ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.slack_event_deliveries FROM PUBLIC;
REVOKE ALL ON public.slack_event_deliveries FROM anon, authenticated, service_role;


-- slack_channels: the org-wide registry of channels TF knows of (what exists;
-- team_slack_channels below is who cares). Powers the discovery/claim UX and
-- caches display names, since Slack event payloads carry only the channel ID.
-- org_id is part of the PK because channel IDs are globally unique and stable
-- across Enterprise Grid / Slack Connect: two orgs each running their own app in
-- a shared channel each get their own registry row. workspace_id is the
-- workspace the channel was last seen through — context for which bot token
-- resolves its name, not a foreign key. name = '' means unresolved; render the
-- raw channel_id. Postgres-only; the SQLite store returns ErrNotApplicableInLocal.
CREATE TABLE public.slack_channels (
    org_id uuid NOT NULL REFERENCES public.orgs(id) ON DELETE CASCADE,
    channel_id text NOT NULL,
    workspace_id text NOT NULL,
    name text NOT NULL DEFAULT '',
    name_resolved_at timestamptz,
    first_seen_at timestamptz NOT NULL DEFAULT now(),
    last_mention_at timestamptz,
    PRIMARY KEY (org_id, channel_id),
    CONSTRAINT sc_channel_populated CHECK (channel_id <> '')
);

ALTER TABLE public.slack_channels ENABLE ROW LEVEL SECURITY;

-- Member-read, system-write: any org member sees the registry, and there is no
-- app-pool write policy at all — every write is a ...System admin-pool method.
CREATE POLICY slack_channels_select ON public.slack_channels FOR SELECT TO tf_app
  USING ((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id));

-- Strip supabase_admin's default grants: tf_app is SELECT-only, writes are admin-pool.
REVOKE ALL ON public.slack_channels FROM PUBLIC;
REVOKE ALL ON public.slack_channels FROM anon, authenticated, service_role;
GRANT SELECT ON public.slack_channels TO tf_app;


-- team_slack_channels: the team <-> channel bind, the tracking half of the
-- registry/tracking split above. Stage-1 scope gate for slack:message routing
-- and the source of a channel's primary owning team. Unlike team_github_repos,
-- org_id is denormalized here so the one-primary invariant can be a partial
-- unique index over (org_id, channel_id): channel IDs are global, so scoping on
-- channel_id alone would forbid two orgs each holding a primary tracker on the
-- same Connect channel. Do not remove the column. No FK to slack_channels: a
-- team may track a channel TF has never seen a mention in. is_primary is never
-- written from the app pool — RLS cannot gate one column, so it is a store-layer
-- contract: ReplaceForTeam always inserts is_primary = false, and promotion or
-- reassignment goes through ReconcilePrimariesSystem / SetPrimarySystem.
CREATE TABLE public.team_slack_channels (
    org_id uuid NOT NULL REFERENCES public.orgs(id) ON DELETE CASCADE,
    team_id uuid NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,
    channel_id text NOT NULL,
    is_primary boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (team_id, channel_id),
    CONSTRAINT tsc_channel_populated CHECK (channel_id <> '')
);

-- At most one tracking row per (org_id, channel_id) may have is_primary = true.
CREATE UNIQUE INDEX team_slack_channels_one_primary
    ON public.team_slack_channels (org_id, channel_id) WHERE is_primary;

-- Serves the cross-team reads that look up every tracker of a channel.
CREATE INDEX team_slack_channels_channel_idx
    ON public.team_slack_channels (org_id, channel_id);

ALTER TABLE public.team_slack_channels ENABLE ROW LEVEL SECURITY;

-- Mirrors team_github_repos_select plus the org guard: team members only.
CREATE POLICY team_slack_channels_select ON public.team_slack_channels FOR SELECT TO tf_app
  USING ((org_id = tf.current_org_id()) AND tf.team_in_current_org(team_id) AND (EXISTS ( SELECT 1
   FROM public.memberships m
  WHERE ((m.team_id = team_slack_channels.team_id) AND (m.user_id = tf.current_user_id())))));

CREATE POLICY team_slack_channels_insert ON public.team_slack_channels FOR INSERT TO tf_app
  WITH CHECK ((org_id = tf.current_org_id()) AND tf.team_in_current_org(team_id) AND tf.user_is_team_admin(team_id));

CREATE POLICY team_slack_channels_delete ON public.team_slack_channels FOR DELETE TO tf_app
  USING ((org_id = tf.current_org_id()) AND tf.team_in_current_org(team_id) AND tf.user_is_team_admin(team_id));

-- No UPDATE policy or grant: the only mutable column is is_primary, which is
-- never app-pool-writable, and RLS cannot gate a single column. The app pool
-- needs INSERT (tracking) and DELETE (untracking) only.
REVOKE ALL ON public.team_slack_channels FROM PUBLIC;
REVOKE ALL ON public.team_slack_channels FROM anon, authenticated, service_role;
GRANT SELECT, INSERT, DELETE ON public.team_slack_channels TO tf_app;


-- === Marketplace V1 ======================================================
-- Within-org publish/copy for prompts + blueprints. Copy-on-publish throughout:
-- a listing holds an immutable, self-contained snapshot
-- (marketplace_listing_versions.snapshot); nothing here FKs into
-- prompts/blueprints, and nothing a consumer copies FKs back to a listing.
-- Provenance rides on marketplace_installs.root_object_id. Multi-mode only —
-- the SQLite store is a stub returning ErrNotApplicableInLocal.
--
-- marketplace_listings SELECT is every org member for published rows, unlike
-- prompts/blueprints (creator-or-same-team). Child tables FK to
-- marketplace_listings(id) and also carry a denormalized org_id so their RLS
-- policies stay a column comparison, not a join into the parent. install_count /
-- vote_count are COUNT(*) joins at read time, so installs and votes stay plain
-- INSERTs a consumer may make rather than needing a system-context write.

CREATE TABLE public.marketplace_listings (
    id                uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id            uuid NOT NULL,
    -- scope/status/kind are app-validated open sets, no CHECK: new values must
    -- be addable with zero DDL.
    scope             text DEFAULT 'org'::text NOT NULL,        -- 'org' now; 'global' in cross-org phase
    kind              text NOT NULL,                             -- 'prompt' | 'blueprint'
    status            text DEFAULT 'published'::text NOT NULL,   -- 'published' | 'delisted'
    name              text NOT NULL,
    description       text DEFAULT ''::text NOT NULL,
    publisher_team_id uuid,             -- listing outlives its publishing team (ON DELETE SET NULL below)
    creator_user_id   uuid,             -- listing outlives its creator (ON DELETE SET NULL below)
    -- team-side blueprint/prompt id; no FK so the listing survives its deletion.
    source_id         uuid,
    current_version   integer DEFAULT 1 NOT NULL,
    created_at        timestamp with time zone DEFAULT now() NOT NULL,
    updated_at        timestamp with time zone DEFAULT now() NOT NULL,
    delisted_at       timestamp with time zone
);

-- Must land before the child CREATE TABLEs below: their inline REFERENCES need
-- a unique constraint on the target column to already exist.
ALTER TABLE ONLY public.marketplace_listings
    ADD CONSTRAINT marketplace_listings_pkey PRIMARY KEY (id);

CREATE TABLE public.marketplace_listing_versions (
    listing_id      uuid NOT NULL REFERENCES public.marketplace_listings(id) ON DELETE CASCADE,
    org_id          uuid NOT NULL,      -- denormalized for RLS, house pattern (cf. blueprint_steps.team_id)
    version         integer NOT NULL,
    snapshot        jsonb NOT NULL,     -- domain.ListingSnapshot, immutable once written
    creator_user_id uuid,
    created_at      timestamp with time zone DEFAULT now() NOT NULL
);

-- Faceting: which event types this listing targets. Mutable browse metadata,
-- distinct from the frozen ListingSnapshot.EventTypes inside a version snapshot.
CREATE TABLE public.marketplace_listing_events (
    listing_id uuid NOT NULL REFERENCES public.marketplace_listings(id) ON DELETE CASCADE,
    org_id     uuid NOT NULL,
    event_type text NOT NULL
);

-- One 'recommend' vote per user per listing; votes and installs only, no rating.
CREATE TABLE public.marketplace_votes (
    listing_id uuid NOT NULL REFERENCES public.marketplace_listings(id) ON DELETE CASCADE,
    org_id     uuid NOT NULL,
    user_id    uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

-- Audit, install counts and provenance. root_object_id is the created copy (a
-- blueprint id for kind=blueprint, a prompt id for kind=prompt) and is not an
-- FK: install history must survive that copy's deletion.
CREATE TABLE public.marketplace_installs (
    id             uuid DEFAULT gen_random_uuid() NOT NULL,
    listing_id     uuid NOT NULL REFERENCES public.marketplace_listings(id) ON DELETE CASCADE,
    org_id         uuid NOT NULL,
    version        integer NOT NULL,
    team_id        uuid NOT NULL,           -- installing team
    user_id        uuid,
    root_object_id uuid,
    created_at     timestamp with time zone DEFAULT now() NOT NULL
);

-- One active listing per source object: republishing reuses the existing listing
-- rather than minting a duplicate (GetActiveBySource).
CREATE UNIQUE INDEX marketplace_listings_source_active ON public.marketplace_listings USING btree (org_id, source_id) WHERE ((status = 'published'::text) AND (source_id IS NOT NULL));

ALTER TABLE ONLY public.marketplace_listing_versions
    ADD CONSTRAINT marketplace_listing_versions_pkey PRIMARY KEY (listing_id, version);

ALTER TABLE ONLY public.marketplace_listing_events
    ADD CONSTRAINT marketplace_listing_events_pkey PRIMARY KEY (listing_id, event_type);

ALTER TABLE ONLY public.marketplace_votes
    ADD CONSTRAINT marketplace_votes_pkey PRIMARY KEY (listing_id, user_id);

ALTER TABLE ONLY public.marketplace_installs
    ADD CONSTRAINT marketplace_installs_pkey PRIMARY KEY (id);

CREATE INDEX idx_marketplace_installs_listing ON public.marketplace_installs USING btree (listing_id, org_id);

ALTER TABLE ONLY public.marketplace_listings
    ADD CONSTRAINT marketplace_listings_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.orgs(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.marketplace_listings
    ADD CONSTRAINT marketplace_listings_publisher_team_id_fkey FOREIGN KEY (publisher_team_id) REFERENCES public.teams(id) ON DELETE SET NULL;
ALTER TABLE ONLY public.marketplace_listings
    ADD CONSTRAINT marketplace_listings_creator_user_id_fkey FOREIGN KEY (creator_user_id) REFERENCES public.users(id) ON DELETE SET NULL;

ALTER TABLE ONLY public.marketplace_listing_versions
    ADD CONSTRAINT marketplace_listing_versions_creator_user_id_fkey FOREIGN KEY (creator_user_id) REFERENCES public.users(id) ON DELETE SET NULL;

ALTER TABLE ONLY public.marketplace_listing_events
    ADD CONSTRAINT marketplace_listing_events_event_type_fkey FOREIGN KEY (event_type) REFERENCES public.events_catalog(id) ON DELETE RESTRICT;

ALTER TABLE ONLY public.marketplace_votes
    ADD CONSTRAINT marketplace_votes_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.marketplace_installs
    ADD CONSTRAINT marketplace_installs_team_id_fkey FOREIGN KEY (team_id) REFERENCES public.teams(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.marketplace_installs
    ADD CONSTRAINT marketplace_installs_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE SET NULL;

CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.marketplace_listings FOR EACH ROW EXECUTE FUNCTION tf.set_updated_at();

ALTER TABLE public.marketplace_listings ENABLE ROW LEVEL SECURITY;

-- Org members browse published listings; publishers also see their delisted ones.
CREATE POLICY marketplace_listings_select ON public.marketplace_listings FOR SELECT
    USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)
            AND ((status = 'published'::text) OR tf.user_can_write_team(publisher_team_id))));
CREATE POLICY marketplace_listings_insert ON public.marketplace_listings FOR INSERT
    WITH CHECK (((org_id = tf.current_org_id()) AND (creator_user_id = tf.current_user_id()) AND tf.user_can_write_team(publisher_team_id)));
CREATE POLICY marketplace_listings_update ON public.marketplace_listings FOR UPDATE
    USING (((org_id = tf.current_org_id()) AND tf.user_can_write_team(publisher_team_id)))
    WITH CHECK (((org_id = tf.current_org_id()) AND tf.user_can_write_team(publisher_team_id)));
CREATE POLICY marketplace_listings_delete ON public.marketplace_listings FOR DELETE
    USING (((org_id = tf.current_org_id()) AND tf.user_can_write_team(publisher_team_id)));

ALTER TABLE public.marketplace_listing_versions ENABLE ROW LEVEL SECURITY;

-- SELECT mirrors listings (org member + published-or-publisher) via EXISTS on
-- the parent, which carries the status; INSERT gates on publisher-team write.
CREATE POLICY marketplace_listing_versions_select ON public.marketplace_listing_versions FOR SELECT
    USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)
            AND (EXISTS ( SELECT 1 FROM public.marketplace_listings l
                          WHERE (l.id = marketplace_listing_versions.listing_id) AND (l.org_id = marketplace_listing_versions.org_id)
                            AND ((l.status = 'published'::text) OR tf.user_can_write_team(l.publisher_team_id))))));
CREATE POLICY marketplace_listing_versions_insert ON public.marketplace_listing_versions FOR INSERT
    WITH CHECK (((org_id = tf.current_org_id())
                 AND (EXISTS ( SELECT 1 FROM public.marketplace_listings l
                              WHERE (l.id = marketplace_listing_versions.listing_id) AND (l.org_id = marketplace_listing_versions.org_id)
                                AND tf.user_can_write_team(l.publisher_team_id)))));

ALTER TABLE public.marketplace_listing_events ENABLE ROW LEVEL SECURITY;

CREATE POLICY marketplace_listing_events_select ON public.marketplace_listing_events FOR SELECT
    USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)
            AND (EXISTS ( SELECT 1 FROM public.marketplace_listings l
                          WHERE (l.id = marketplace_listing_events.listing_id) AND (l.org_id = marketplace_listing_events.org_id)
                            AND ((l.status = 'published'::text) OR tf.user_can_write_team(l.publisher_team_id))))));
CREATE POLICY marketplace_listing_events_insert ON public.marketplace_listing_events FOR INSERT
    WITH CHECK (((org_id = tf.current_org_id())
                 AND (EXISTS ( SELECT 1 FROM public.marketplace_listings l
                              WHERE (l.id = marketplace_listing_events.listing_id) AND (l.org_id = marketplace_listing_events.org_id)
                                AND tf.user_can_write_team(l.publisher_team_id)))));
-- DELETE mirrors INSERT: PublishVersion replaces the facet set.
CREATE POLICY marketplace_listing_events_delete ON public.marketplace_listing_events FOR DELETE
    USING (((org_id = tf.current_org_id())
            AND (EXISTS ( SELECT 1 FROM public.marketplace_listings l
                         WHERE (l.id = marketplace_listing_events.listing_id) AND (l.org_id = marketplace_listing_events.org_id)
                           AND tf.user_can_write_team(l.publisher_team_id)))));

ALTER TABLE public.marketplace_votes ENABLE ROW LEVEL SECURITY;

CREATE POLICY marketplace_votes_select ON public.marketplace_votes FOR SELECT
    USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)));
CREATE POLICY marketplace_votes_insert ON public.marketplace_votes FOR INSERT
    WITH CHECK (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id) AND (user_id = tf.current_user_id())));
CREATE POLICY marketplace_votes_delete ON public.marketplace_votes FOR DELETE
    USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id) AND (user_id = tf.current_user_id())));

ALTER TABLE public.marketplace_installs ENABLE ROW LEVEL SECURITY;

CREATE POLICY marketplace_installs_select ON public.marketplace_installs FOR SELECT
    USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)));
-- Write role on the *installing* team, not the publishing team.
CREATE POLICY marketplace_installs_insert ON public.marketplace_installs FOR INSERT
    WITH CHECK (((org_id = tf.current_org_id()) AND tf.user_can_write_team(team_id)));

