-- Denormalized aggregates across every copy of a listing. Copy linkage is
-- marketplace_installs.root_object_id, joined to conversations.prompt_id for
-- kind=prompt and blueprint_runs.blueprint_id for kind=blueprint. Written only
-- by MarketplaceStore.RecomputeStatsSystem on the admin pool — the aggregate
-- crosses teams, so it cannot be computed under RLS; no write policy is
-- declared below. total_runs counts runs from deleted copies (root_object_id
-- survives deletion); teams_using requires the copy to still exist.
CREATE TABLE public.marketplace_listing_stats (
    listing_id   uuid NOT NULL REFERENCES public.marketplace_listings(id) ON DELETE CASCADE,
    org_id       uuid NOT NULL,   -- denormalized for RLS, house pattern (cf. marketplace_listing_versions.org_id)
    teams_using  integer NOT NULL DEFAULT 0,
    total_runs   integer NOT NULL DEFAULT 0,
    -- NULL until total_runs > 0 — never a fake 0% success rate.
    success_rate double precision,
    last_run_at  timestamp with time zone,
    computed_at  timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE ONLY public.marketplace_listing_stats
    ADD CONSTRAINT marketplace_listing_stats_pkey PRIMARY KEY (listing_id);

ALTER TABLE public.marketplace_listing_stats ENABLE ROW LEVEL SECURITY;

-- SELECT-only, mirroring marketplace_listings' org-member visibility; the row
-- carries no publisher-team distinction to gate on.
CREATE POLICY marketplace_listing_stats_select ON public.marketplace_listing_stats FOR SELECT
    USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)));

GRANT ALL ON TABLE public.marketplace_listing_stats TO postgres;
GRANT ALL ON TABLE public.marketplace_listing_stats TO anon;
GRANT ALL ON TABLE public.marketplace_listing_stats TO authenticated;
GRANT ALL ON TABLE public.marketplace_listing_stats TO service_role;
GRANT SELECT ON TABLE public.marketplace_listing_stats TO tf_app;


-- instances: the fleet membership registry every TF process registers into at
-- boot and refreshes by heartbeat — control pods too, not just executors.
-- id is text because it is minted outside Postgres, by a file under
-- <TF_STATE_ROOT>/instance-id, so identity travels with the state root; Register
-- upserts on id and bumps boot_epoch. The capacity columns (max_runs,
-- active_runs, mem_*, dispatch_gated) are NULL on pure-control rows.
-- Admin-pool-only system table: no org_id, so RLS is enabled with NO policy
-- (deny-by-default to non-BYPASSRLS roles) plus REVOKE ALL.
CREATE TABLE public.instances (
    id                 text NOT NULL,
    role               text NOT NULL,
    version            text NOT NULL,
    boot_epoch         bigint NOT NULL,
    started_at         timestamp with time zone NOT NULL,
    last_heartbeat_at  timestamp with time zone NOT NULL,
    draining           boolean NOT NULL DEFAULT false,
    max_runs           integer,
    active_runs        integer,
    mem_total_mb       integer,
    mem_available_mb   integer,
    dispatch_gated     boolean,
    labels             jsonb,
    -- This boot's ephemeral X25519 public key (base64), minted in memory at
    -- process start. Written only by Register's INSERT and ON CONFLICT re-stamp,
    -- never the heartbeat: a restart must get a fresh key. NULL for a control
    -- row that never provisions or claims conversations.
    pubkey             text
);

ALTER TABLE ONLY public.instances
    ADD CONSTRAINT instances_pkey PRIMARY KEY (id);

ALTER TABLE public.instances ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.instances FROM PUBLIC;
REVOKE ALL ON public.instances FROM anon, authenticated, service_role;

-- leases: leader election for the control plane. One row today
-- (name='background-brain'), name-keyed so per-org sharding is more rows.
-- term is the fencing token: +1 on every acquisition, never on a renewal.
-- Acquisition takes the row when renewed_at < now() - TTL; a renewal matching
-- 0 rows means the lease was taken and the holder demotes. Comparisons here
-- run in DB time; a holder's own self-demotion runs on its monotonic clock.
-- First boot seeds the row with INSERT ... ON CONFLICT (name) DO NOTHING
-- (holder_id='', renewed_at far in the past) before the acquisition UPDATE.
-- Admin-pool-only system table: no org_id, RLS with NO policy plus REVOKE ALL.
-- No SQLite counterpart — local mode never elects.
CREATE TABLE public.leases (
    name         text NOT NULL,
    holder_id    text NOT NULL,
    term         bigint NOT NULL,
    acquired_at  timestamp with time zone NOT NULL,
    renewed_at   timestamp with time zone NOT NULL
);

ALTER TABLE ONLY public.leases
    ADD CONSTRAINT leases_pkey PRIMARY KEY (name);

ALTER TABLE public.leases ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.leases FROM PUBLIC;
REVOKE ALL ON public.leases FROM anon, authenticated, service_role;

-- poll_readiness: org-scoped state for the "config took effect" announce toast
-- and the /api/jira/stock readiness gate. Under the control/standby split the
-- pod running the poller is not the one serving the request, so this must be
-- readable by every control pod. One row per (org_id, source), source is
-- 'github' or 'jira'. Ready = last_poll_at IS NOT NULL AND (restarted_at IS
-- NULL OR last_poll_at > restarted_at). announce_pending is a one-shot flag
-- consumed atomically so racing pods can't double-fire the toast.
-- Store methods take an explicit orgID and run on the admin pool; the handler
-- has already resolved and authorized the org from session claims.
CREATE TABLE public.poll_readiness (
    org_id            text NOT NULL,
    source            text NOT NULL,
    restarted_at      timestamp with time zone,
    last_poll_at      timestamp with time zone,
    announce_pending  boolean NOT NULL DEFAULT false
);

ALTER TABLE ONLY public.poll_readiness
    ADD CONSTRAINT poll_readiness_pkey PRIMARY KEY (org_id, source);

ALTER TABLE public.poll_readiness ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.poll_readiness FROM PUBLIC;
REVOKE ALL ON public.poll_readiness FROM anon, authenticated, service_role;


-- org_event_sources: per-(org, source) policy — today, whether an org admin
-- turned a source off: it is not polled, produces no events, mints no tasks,
-- and resolves no credential for an agent. The credential stays bound, which
-- is what makes this reversible where unbinding it is not.
-- Its own table rather than columns on org_settings: the source vocabulary is
-- a runtime registry, so a column per source would be DDL in both dialects,
-- and org_settings is a whole-row write behind a `version` token.
-- kind carries no FK — it names a registry entry this build may not carry, so
-- such a row is inert; the application decides which sources may be disabled
-- (internal/eventsource.Disableable). disabled_by carries none either: the
-- who-did-what trail lives in access_changes and a deleted admin must not
-- rewrite policy. base_url and poll_interval are NULL when no override is
-- recorded, never "use a default"; base_url is refused for a source with no
-- self-host story. Both are owned by OrgsStore, the disabled_* columns by
-- OrgEventSourceStore.SetDisabled.
CREATE TABLE public.org_event_sources (
    org_id        uuid NOT NULL,
    kind          text NOT NULL,
    disabled      boolean DEFAULT false NOT NULL,
    disabled_at   timestamp with time zone,
    disabled_by   uuid,
    base_url      text,
    poll_interval interval
);

ALTER TABLE ONLY public.org_event_sources
    ADD CONSTRAINT org_event_sources_pkey PRIMARY KEY (org_id, kind);

ALTER TABLE ONLY public.org_event_sources
    ADD CONSTRAINT org_event_sources_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.orgs(id) ON DELETE CASCADE;

ALTER TABLE public.org_event_sources ENABLE ROW LEVEL SECURITY;

-- Member SELECT, admin write — the same split as org_settings. A member must
-- be able to read it: it is what renders why their own event handler sits
-- inert. The handler's RequireOrgAdmin is the enforcement point callers see.
CREATE POLICY org_event_sources_select ON public.org_event_sources FOR SELECT USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)));
CREATE POLICY org_event_sources_insert ON public.org_event_sources FOR INSERT WITH CHECK (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id)));
CREATE POLICY org_event_sources_update ON public.org_event_sources FOR UPDATE USING (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id))) WITH CHECK (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id)));
CREATE POLICY org_event_sources_delete ON public.org_event_sources FOR DELETE USING (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id)));

REVOKE ALL ON public.org_event_sources FROM PUBLIC;
REVOKE ALL ON public.org_event_sources FROM anon, authenticated, service_role;

GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.org_event_sources TO tf_app;


-- model_availability: per (org, provider, model) evidence that the org's
-- credentials can invoke that model, established by spending one minimal real
-- request. A probe rather than a control-plane lookup because no provider API
-- answers uniformly — Bedrock's ListFoundationModels reports what the region
-- carries, not what the account was granted, and returns base ids rather than
-- invocable inference-profile ids.
--   green   a probe succeeded; only a manual re-test rewrites the row.
--   red     the provider answered and refused; cleared by a later success.
--   absent  never probed, or every attempt was inconclusive (5xx, timeout,
--           dial failure) — those write nothing, so a bad provider minute
--           cannot hide a model that works.
-- No TTL and no sweeper: every transition comes from a user gesture. provider
-- is in the PK because the row establishes that a credential path works.
-- model_key has no FK — the catalog is a compiled-in file, not a table.
CREATE TABLE public.model_availability (
    org_id     uuid NOT NULL,
    provider   text NOT NULL,
    model_key  text NOT NULL,
    state      text NOT NULL,
    checked_at timestamp with time zone NOT NULL,
    detail     text DEFAULT ''::text NOT NULL
);

ALTER TABLE ONLY public.model_availability
    ADD CONSTRAINT model_availability_pkey PRIMARY KEY (org_id, provider, model_key);

ALTER TABLE ONLY public.model_availability
    ADD CONSTRAINT model_availability_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.orgs(id) ON DELETE CASCADE;

-- Two stored values only; an inconclusive probe writes no row, so a third
-- value would mean some caller invented one.
ALTER TABLE ONLY public.model_availability
    ADD CONSTRAINT model_availability_state_check CHECK ((state = ANY (ARRAY['green'::text, 'red'::text])));

ALTER TABLE public.model_availability ENABLE ROW LEVEL SECURITY;

-- Member SELECT, admin write. The read is member-level because the model
-- catalog read is: a team admin must see why a model is badged unavailable.
-- The write is admin because each row is the receipt for a real, billed request.
CREATE POLICY model_availability_select ON public.model_availability FOR SELECT USING (((org_id = tf.current_org_id()) AND tf.user_has_org_access(org_id)));
CREATE POLICY model_availability_insert ON public.model_availability FOR INSERT WITH CHECK (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id)));
CREATE POLICY model_availability_update ON public.model_availability FOR UPDATE USING (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id))) WITH CHECK (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id)));
CREATE POLICY model_availability_delete ON public.model_availability FOR DELETE USING (((org_id = tf.current_org_id()) AND tf.user_is_org_admin(org_id)));

REVOKE ALL ON public.model_availability FROM PUBLIC;
REVOKE ALL ON public.model_availability FROM anon, authenticated, service_role;

GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.model_availability TO tf_app;


-- placement_overrides: human intent that wins over the computed
-- capacity-weighted rendezvous order for one placement key — a manual pin or a
-- hot-key replica count, nothing else (drain lives on the instances row).
-- Checked before the hash and expected to stay nearly empty. key_kind is
-- 'repo', key_value "owner/repo"; org_id is plain text, matching the
-- rendezvous key's own org fold. A pin wins when both intents are set. Neither
-- is FK-validated — a pin to a retired instance self-heals via the claim's
-- aging tier. Admin-pool-only system table, same posture as instances: RLS
-- with NO policy plus REVOKE ALL, org_id bound by argument.
CREATE TABLE public.placement_overrides (
    org_id             text NOT NULL,
    key_kind           text NOT NULL,
    key_value          text NOT NULL,
    pinned_instance_id text,
    replicas           integer NOT NULL DEFAULT 0,
    updated_at         timestamp with time zone NOT NULL DEFAULT now()
);

ALTER TABLE ONLY public.placement_overrides
    ADD CONSTRAINT placement_overrides_pkey PRIMARY KEY (org_id, key_kind, key_value);

ALTER TABLE public.placement_overrides ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.placement_overrides FROM PUBLIC;
REVOKE ALL ON public.placement_overrides FROM anon, authenticated, service_role;


-- instance_stats: 1-minute telemetry samples, one row per pod per minute. The
-- instances row carries the current snapshot; this carries history plus fields
-- too transient for the 4s heartbeat. Every metric column is nullable — a
-- control pod has no runs, a non-Linux host cannot report cpu/load/oom, and a
-- partial sample still beats dropping it. mem_available_mb comes from hostmem
-- (cgroup-aware), never /proc/meminfo. Admin-pool-only system table: no
-- org_id, RLS with NO policy plus REVOKE ALL. A ~30d reaper trims it.
CREATE TABLE public.instance_stats (
    instance_id       text NOT NULL,
    at                timestamp with time zone NOT NULL,
    active_runs       integer,
    queued_visible    integer,
    mem_available_mb  integer,
    cpu_pct           real,
    load1             real,
    claims            integer,
    spawn_p50_ms      integer,
    oom_kills         integer
);

ALTER TABLE ONLY public.instance_stats
    ADD CONSTRAINT instance_stats_pkey PRIMARY KEY (instance_id, at);

-- The reaper and the fleet-wide timeseries both key on `at` alone, which the
-- PK's leading instance_id cannot serve.
CREATE INDEX instance_stats_at_idx ON public.instance_stats USING btree (at);

ALTER TABLE public.instance_stats ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.instance_stats FROM PUBLIC;
REVOKE ALL ON public.instance_stats FROM anon, authenticated, service_role;


-- sandbox_stats: one row per live jail per sampler tick, read by the
-- per-conversation usage-over-time surface. It is the shape of consumption
-- while a run executes; the claim's teardown actuals (claims.peak_mem_mb /
-- cpu_usec) are the truth, and the two are never reconciled — a periodic
-- sampler misses sub-minute spikes. cpu_usec_cum is cumulative, not a rate, so
-- a dropped tick self-heals into a wider interval. Both metric columns are
-- nullable: the sampler writes whatever it could read. claim_id has no FK —
-- this is a best-effort telemetry batch that must never be rejected by
-- referential integrity, bounded by a ~30d age reaper. Admin-pool-only system
-- table: no org_id, RLS with NO policy plus REVOKE ALL.
CREATE TABLE public.sandbox_stats (
    claim_id        uuid NOT NULL,
    at              timestamp with time zone NOT NULL,
    mem_current_mb  integer,
    cpu_usec_cum    bigint
);

-- The PK is also the per-claim series index, and makes a retried tick an
-- idempotent no-op via ON CONFLICT DO NOTHING.
ALTER TABLE ONLY public.sandbox_stats
    ADD CONSTRAINT sandbox_stats_pkey PRIMARY KEY (claim_id, at);

-- The reaper deletes by age alone, which the PK's leading claim_id cannot serve.
CREATE INDEX sandbox_stats_at_idx ON public.sandbox_stats USING btree (at);

ALTER TABLE public.sandbox_stats ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.sandbox_stats FROM PUBLIC;
REVOKE ALL ON public.sandbox_stats FROM anon, authenticated, service_role;


-- operators: the deployment-operator flag gating the fleet console. Deployment
-- scoped, so an operator is org-less rather than a member role, and is managed
-- only through `triagefactory operator add|remove|list`; the trust boundary is
-- shell access. Keyed on the lower-cased email, not a user id: it is what the
-- CLI names and what every verified session carries, so an operator can be
-- authorized before their first login. Admin-pool-only system table: no
-- org_id, RLS with NO policy plus REVOKE ALL.
CREATE TABLE public.operators (
    email     text NOT NULL,
    added_at  timestamp with time zone NOT NULL DEFAULT now(),
    -- The OS user that ran the CLI; provenance only, not an authz input.
    added_by  text
);

ALTER TABLE ONLY public.operators
    ADD CONSTRAINT operators_pkey PRIMARY KEY (email);

ALTER TABLE public.operators ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.operators FROM PUBLIC;
REVOKE ALL ON public.operators FROM anon, authenticated, service_role;


-- ws_outbox: overflow storage for the tf_ws backplane. NOTIFY caps a payload
-- at ~8 KB, so an event over the inline threshold (TF_WS_INLINE_MAX_B, default
-- 6 KB) lands here and the NOTIFY carries only a row ref. Insert and NOTIFY
-- share a transaction; a missing row (rollback after NOTIFY was buffered, or a
-- TTL reap) drops the event, consistent with tf_ws being lossy by contract.
-- TTL 60 s (TF_WS_OUTBOX_TTL_SECONDS), and any pod's timer may reap since a
-- DELETE by age is concurrency-safe — not leader-gated. Admin-pool-only: no
-- org_id (the payload carries it), RLS with NO policy plus REVOKE ALL.
CREATE TABLE public.ws_outbox (
    id          bigserial NOT NULL,
    payload     jsonb NOT NULL,
    created_at  timestamp with time zone NOT NULL DEFAULT now()
);

ALTER TABLE ONLY public.ws_outbox
    ADD CONSTRAINT ws_outbox_pkey PRIMARY KEY (id);

CREATE INDEX ws_outbox_created_at_idx ON public.ws_outbox USING btree (created_at);

ALTER TABLE public.ws_outbox ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.ws_outbox FROM PUBLIC;
REVOKE ALL ON public.ws_outbox FROM anon, authenticated, service_role;


-- ws_presence: cross-pod presence for the unattended-prompt fast-deny and the
-- fleet dashboard's live-viewer count — a Hub only sees its own pod's sockets.
-- Every control pod upserts one row per (user_id, conn_id) on a ~15 s heartbeat
-- (TF_WS_PRESENCE_HEARTBEAT_SECONDS); the writer qualifies conn_id with its
-- instance id, since that id is unique only within one process. A row is live
-- iff last_seen is within TF_WS_PRESENCE_TTL_SECONDS (45 s), checked at read
-- time; nothing deletes on disconnect, so dead rows age out of every live read.
-- conn_id comes from a never-reused per-boot counter, so a separate reaper
-- (TF_WS_PRESENCE_ROW_TTL_SECONDS) trims old rows purely to bound storage.
-- Admin-pool-only system table: org_id is a read-time filter on plumbing rows,
-- not tenant content, so RLS is enabled with NO policy plus REVOKE ALL.
CREATE TABLE public.ws_presence (
    user_id     text NOT NULL,
    conn_id     text NOT NULL,
    org_id      text NOT NULL,
    instance_id text NOT NULL,
    viewing     text NOT NULL DEFAULT ''::text,
    visible     boolean NOT NULL DEFAULT false,
    last_seen   timestamp with time zone NOT NULL DEFAULT now()
);

ALTER TABLE ONLY public.ws_presence
    ADD CONSTRAINT ws_presence_pkey PRIMARY KEY (user_id, conn_id);

CREATE INDEX ws_presence_org_last_seen_idx ON public.ws_presence USING btree (org_id, last_seen);

ALTER TABLE public.ws_presence ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.ws_presence FROM PUBLIC;
REVOKE ALL ON public.ws_presence FROM anon, authenticated, service_role;


-- conversation_signals: the cross-pod conversation-control outbox — a control
-- pod's delivery of cancel/interrupt/steer/permission/inject to the executor
-- owning the conversation's live process (claims.executor_id), for when the
-- local process registry misses. 'inject' is here because additive-event
-- injection routes the same way; the staged-injection fallback (an undelivered
-- messages row) remains for parked conversations. `payload` carries steer text,
-- the permission decision, or the injection body, riding the row rather than
-- the NOTIFY payload so the 8 KB cap does not apply. `target` is the executor
-- id (instances.id, text), no FK, same as claims.executor_id — a retired
-- instance leaves a signal to expire harmlessly. Acked rows purge after 24h
-- (TF_CONVERSATION_SIGNAL_PURGE_AFTER). Postgres-only: local mode is always its
-- own run's owner, so internal/db/sqlite/conversation_signals.go is a stub
-- returning ErrNotApplicableInLocal. RLS with NO policy plus REVOKE ALL.
CREATE TABLE public.conversation_signals (
    id         bigint GENERATED BY DEFAULT AS IDENTITY,
    org_id     uuid NOT NULL,
    conversation_id     uuid NOT NULL,
    kind       text NOT NULL,
    payload    jsonb,
    target     text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    acked_at   timestamp with time zone,
    ack_result text,
    CONSTRAINT conversation_signals_kind_check CHECK ((kind = ANY (ARRAY['cancel'::text, 'interrupt'::text, 'steer'::text, 'permission'::text, 'inject'::text])))
);

ALTER TABLE ONLY public.conversation_signals
    ADD CONSTRAINT conversation_signals_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.conversation_signals
    ADD CONSTRAINT conversation_signals_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.orgs(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.conversation_signals
    ADD CONSTRAINT conversation_signals_conversation_id_org_id_fkey FOREIGN KEY (conversation_id, org_id) REFERENCES public.conversations(id, org_id) ON DELETE CASCADE;

-- The owner's apply-loop scan: unacked rows targeting me, oldest id first.
-- Ascending id across the target preserves per-conversation order too.
CREATE INDEX idx_conversation_signals_target_unacked ON public.conversation_signals USING btree (target, id) WHERE (acked_at IS NULL);
-- The 24h purge sweep.
CREATE INDEX idx_conversation_signals_acked ON public.conversation_signals USING btree (acked_at) WHERE (acked_at IS NOT NULL);

ALTER TABLE public.conversation_signals ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.conversation_signals FROM PUBLIC;
REVOKE ALL ON public.conversation_signals FROM anon, authenticated, service_role;


-- claims: one row per executor engagement with a conversation. At most one
-- active (released_at IS NULL) claim per conversation. Credential columns
-- stay NULL in local mode.
CREATE TABLE public.claims (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    executor_id text NOT NULL,
    -- boot_epoch pairs with executor_id: the boot self-sweep releases only
    -- claims where executor_id = self AND boot_epoch < the current epoch.
    boot_epoch bigint NOT NULL,
    -- Per-engagement credential sidecar's X25519 public key (base64),
    -- published when the executor parks in phase='awaiting_credentials'.
    cred_pubkey text,
    -- Setup/parked sub-state of a live engagement: 'fetching' | 'cloning' |
    -- 'agent_starting' | 'awaiting_credentials'. NULL = the agent process is
    -- live, or the claim is released and its phase is inert history.
    phase text,
    claimed_at timestamp with time zone DEFAULT now() NOT NULL,
    -- NULL = this claim is live. Stamped once, on release.
    released_at timestamp with time zone,
    -- App-validated: 'completed' | 'failed' | 'cancelled' | 'requeued' |
    -- 'parked' | 'reaped'. NULL while live.
    outcome text,
    error text,
    -- Runtime-reported per invocation. Dollars and tokens live in messages.
    duration_ms integer,
    num_turns integer,
    -- Measured sandbox cost, read from the cell's cgroup (memory.peak,
    -- cpu.stat usage_usec) at teardown. NULL = not measured, never zero: local
    -- mode has no sandbox and a pre-5.19 kernel has no memory.peak. The CPU
    -- figure includes the gVisor sentry's systrap overhead.
    peak_mem_mb integer,
    cpu_usec bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE ONLY public.claims
    ADD CONSTRAINT claims_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.claims
    ADD CONSTRAINT claims_id_org_unique UNIQUE (id, org_id);
ALTER TABLE ONLY public.claims
    ADD CONSTRAINT claims_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.orgs(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.claims
    ADD CONSTRAINT claims_conversation_id_org_id_fkey FOREIGN KEY (conversation_id, org_id) REFERENCES public.conversations(id, org_id) ON DELETE CASCADE;

-- A conversation has at most one live executor engagement.
CREATE UNIQUE INDEX idx_claims_one_active ON public.claims USING btree (conversation_id) WHERE (released_at IS NULL);
CREATE INDEX idx_claims_conversation ON public.claims USING btree (conversation_id, claimed_at);
-- The credential provisioner's backstop sweep scans live claims parked in
-- phase='awaiting_credentials'.
CREATE INDEX idx_claims_active_phase ON public.claims USING btree (phase) WHERE (released_at IS NULL AND phase IS NOT NULL);

-- App-pool visibility composes through the conversation; writes are
-- system-side.
ALTER TABLE public.claims ENABLE ROW LEVEL SECURITY;

CREATE POLICY claims_select ON public.claims FOR SELECT USING ((EXISTS ( SELECT 1
   FROM public.conversations c
  WHERE (c.id = claims.conversation_id))));

GRANT ALL ON TABLE public.claims TO postgres;
GRANT ALL ON TABLE public.claims TO anon;
GRANT ALL ON TABLE public.claims TO authenticated;
GRANT ALL ON TABLE public.claims TO service_role;
GRANT SELECT ON TABLE public.claims TO tf_app;
GRANT SELECT, INSERT, UPDATE ON TABLE public.claims TO tf_system;

-- Declared late: claims_id_org_unique must exist first. ON DELETE SET NULL so
-- the conversation cascade to claims and to messages never orders wrong.
ALTER TABLE ONLY public.messages
    ADD CONSTRAINT messages_claim_id_fkey FOREIGN KEY (claim_id) REFERENCES public.claims(id) ON DELETE SET NULL;


-- claim_credentials: the sealed per-claim credential bundle channel. The brain
-- seals an engagement's LLM/GitHub/Jira credentials (credseal, X25519 sealed
-- box) to the claim's published cred_pubkey; one row per claim, replaced
-- wholesale, never merged. boot_epoch and include_tools ride in cleartext
-- beside the blob: the epoch so the executor rejects a bundle sealed for an
-- earlier boot before unsealing, include_tools so it can compose the run's
-- <tools> section from the org's available event-source kinds (NULL = nothing
-- stamped and the reader falls back; '[]' = nothing available).
--
-- Admin-pool only, no RLS policy and no app-pool grant: credential-bearing
-- ciphertext is never a request-handler surface.
CREATE TABLE public.claim_credentials (
    claim_id      uuid NOT NULL,
    org_id        uuid NOT NULL,
    executor_id   text NOT NULL,
    boot_epoch    bigint NOT NULL,
    sealed        bytea NOT NULL,
    include_tools jsonb,
    created_at    timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE ONLY public.claim_credentials
    ADD CONSTRAINT claim_credentials_pkey PRIMARY KEY (claim_id);

ALTER TABLE ONLY public.claim_credentials
    ADD CONSTRAINT claim_credentials_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.orgs(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.claim_credentials
    ADD CONSTRAINT claim_credentials_claim_id_org_id_fkey FOREIGN KEY (claim_id, org_id) REFERENCES public.claims(id, org_id) ON DELETE CASCADE;

ALTER TABLE public.claim_credentials ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.claim_credentials FROM PUBLIC;
REVOKE ALL ON public.claim_credentials FROM anon, authenticated, service_role;

-- The executor polls for the bundle sealed to its pubkey and deletes the row
-- at teardown. No INSERT: only the brain provisions, on its own admin pool.
GRANT SELECT, DELETE ON TABLE public.claim_credentials TO tf_system;


-- conversation_permissions: the durable record of every tool-approval prompt a
-- conversation raised and how it was answered — an address a refresh or a
-- second tab can read, and the only place an approval is recorded at all.
-- Nothing writes here in a multi deployment today (native runtime has no
-- permission gate, sandboxed SDK runs auto-approve).
CREATE TABLE public.conversation_permissions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    -- The engagement that asked. A row whose claim is no longer the
    -- conversation's active claim is not pending, however the row itself reads.
    claim_id uuid,
    -- The assistant row carrying the gated tool_use block. NULL on the SDK
    -- path, where the prompt is raised before that row exists.
    message_id bigint,
    -- The SDK's toolUseID — matches messages.tool_calls[].id and the answering
    -- row's tool_call_id, so a decision ties back to the call it authorized.
    tool_call_id text NOT NULL,
    tool_name text NOT NULL,
    input_json text,
    -- The SDK's pre-rendered prompt sentence, absent when it rendered none;
    -- consumers must still be able to rebuild a headline from tool_name + input.
    title text,
    -- state is app-validated: 'pending' | 'allowed' | 'denied' | 'expired'.
    state text NOT NULL,
    -- reason is app-validated: 'user' | 'timeout' | 'absent' | 'closing' |
    -- 'claim_lost'.
    reason text,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    decided_by uuid,
    decided_at timestamp with time zone,
    -- How long the prompt stood open, stamped at resolution from the row's own
    -- requested_at (the two timestamps can come from different clocks). NULL
    -- while pending; meaningful on every terminal state, not just approvals.
    waited_ms integer
);

ALTER TABLE ONLY public.conversation_permissions
    ADD CONSTRAINT conversation_permissions_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.conversation_permissions
    ADD CONSTRAINT conversation_permissions_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.orgs(id) ON DELETE CASCADE;
-- No ON DELETE CASCADE from conversations: an audit record whose value is
-- outliving the work must survive cleanup of the work.
ALTER TABLE ONLY public.conversation_permissions
    ADD CONSTRAINT conversation_permissions_conversation_id_org_id_fkey FOREIGN KEY (conversation_id, org_id) REFERENCES public.conversations(id, org_id);
ALTER TABLE ONLY public.conversation_permissions
    ADD CONSTRAINT conversation_permissions_claim_id_fkey FOREIGN KEY (claim_id) REFERENCES public.claims(id) ON DELETE SET NULL;
ALTER TABLE ONLY public.conversation_permissions
    ADD CONSTRAINT conversation_permissions_message_id_fkey FOREIGN KEY (message_id) REFERENCES public.messages(id) ON DELETE SET NULL;
ALTER TABLE ONLY public.conversation_permissions
    ADD CONSTRAINT conversation_permissions_decided_by_fkey FOREIGN KEY (decided_by) REFERENCES public.users(id) ON DELETE SET NULL;

-- One row per gated call, which also makes the writer's insert idempotent.
CREATE UNIQUE INDEX idx_conv_perms_call ON public.conversation_permissions USING btree (conversation_id, tool_call_id);
-- The read this table exists for: "what is this conversation waiting on".
CREATE INDEX idx_conv_perms_pending ON public.conversation_permissions USING btree (conversation_id) WHERE (state = 'pending');

-- App-pool visibility composes through the conversation; writes are
-- system-side.
ALTER TABLE public.conversation_permissions ENABLE ROW LEVEL SECURITY;

CREATE POLICY conversation_permissions_select ON public.conversation_permissions FOR SELECT USING ((EXISTS ( SELECT 1
   FROM public.conversations c
  WHERE (c.id = conversation_permissions.conversation_id))));

GRANT ALL ON TABLE public.conversation_permissions TO postgres;
GRANT ALL ON TABLE public.conversation_permissions TO anon;
GRANT ALL ON TABLE public.conversation_permissions TO authenticated;
GRANT ALL ON TABLE public.conversation_permissions TO service_role;
GRANT SELECT ON TABLE public.conversation_permissions TO tf_app;
GRANT SELECT, INSERT, UPDATE ON TABLE public.conversation_permissions TO tf_system;

-- workspace_snapshots: the durable lifecycle of one snapshot key's workspace
-- blob — pending, written, or failed. The blob store's silence cannot
-- distinguish a persist in flight from one that failed, from a workspace that
-- never existed; this row separates them. writer_claim_id is the stale-write
-- guard: a writer re-reads it before uploading and the completion CAS keys on
-- it, so a displaced writer cannot close out a write it no longer owns. No FK
-- on it — a claim's fate must not decide whether the blob's state is knowable.
CREATE TABLE public.workspace_snapshots (
    org_id uuid NOT NULL,
    blueprint_run_id uuid NOT NULL,
    state text NOT NULL,
    writer_claim_id uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workspace_snapshots_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'written'::text, 'failed'::text])))
);

ALTER TABLE ONLY public.workspace_snapshots
    ADD CONSTRAINT workspace_snapshots_pkey PRIMARY KEY (org_id, blueprint_run_id);

ALTER TABLE ONLY public.workspace_snapshots
    ADD CONSTRAINT workspace_snapshots_blueprint_run_id_org_id_fkey FOREIGN KEY (blueprint_run_id, org_id) REFERENCES public.blueprint_runs(id, org_id) ON DELETE CASCADE;

-- Admin-pool only, like claim_credentials: every caller is an executor-side
-- teardown or a system sweep, so RLS is on with no policy and no app grant.
ALTER TABLE public.workspace_snapshots ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.workspace_snapshots FROM PUBLIC;
REVOKE ALL ON public.workspace_snapshots FROM anon, authenticated, service_role;

-- The executor writes the lifecycle, reads it back for the pre-Put supersede
-- check, and deletes it with the blob at cleanup and in the retention reaper.
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.workspace_snapshots TO tf_system;


-- user_api_tokens: per-user, org-scoped bearer credentials — a sealed session
-- cursor. A session is (user, movable active_org); a token is the same pair with
-- the org fixed at mint, which is why org_id is NOT NULL: there is no
-- no-tenant token, and multi-org automation holds one token per org.
-- PG-only like sessions — local mode's synthetic identity is already headless,
-- so there is nothing there for a token to be.
-- Only sha256 of the full literal token (the "tf_" prefix included) is stored;
-- the plaintext escapes exactly once, from the mint call. The hash is unique so
-- lookup is an index probe rather than a scan-and-compare. token_prefix is the
-- first 11 characters of that plaintext ("tf_" + 8), kept so a list can name a
-- token without holding the secret.
-- name is deliberately NOT unique: rotation is mint-a-same-named-replacement,
-- deploy, revoke-the-old, and a unique name would force a rename into every
-- rotation.
-- allowed_cidrs is defense in depth: the column carries ranges and decides
-- nothing, and whatever matches a request against them is only as trustworthy
-- as the deployment's TF_TRUSTED_PROXY_CIDR. NULL means no restriction; an
-- empty array would be a token that can never be used, so the cardinality
-- CHECK refuses one.
-- expires_at is the token's own stored expiry. The org's
-- org_settings.api_token_max_age_days cap is applied at USE, not stored here, so
-- tightening it shortens every existing token in the org at once.
CREATE TABLE public.user_api_tokens (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
    org_id        uuid NOT NULL REFERENCES public.orgs(id) ON DELETE CASCADE,
    name          text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100),
    token_hash    bytea NOT NULL,
    token_prefix  text  NOT NULL,
    allowed_cidrs cidr[] CHECK (allowed_cidrs IS NULL OR cardinality(allowed_cidrs) BETWEEN 1 AND 20),
    created_at    timestamp with time zone NOT NULL DEFAULT now(),
    last_used_at  timestamp with time zone,
    expires_at    timestamp with time zone CHECK (expires_at IS NULL OR expires_at > created_at),
    revoked_at    timestamp with time zone
);

CREATE UNIQUE INDEX user_api_tokens_hash_uniq ON public.user_api_tokens (token_hash);
CREATE INDEX user_api_tokens_user_org_idx ON public.user_api_tokens (user_id, org_id);

ALTER TABLE public.user_api_tokens ENABLE ROW LEVEL SECURITY;

-- The sessions shape: a row is the user's own credential, so the predicate is
-- the owner and nothing else. internal/apitokens runs on the admin pool (token
-- lookup happens before any claims exist), so these policies defend the
-- app-pool surface a later "list my tokens" reader would use, exactly as
-- sessions' do.
CREATE POLICY user_api_tokens_modify ON public.user_api_tokens USING ((user_id = tf.current_user_id())) WITH CHECK ((user_id = tf.current_user_id()));
CREATE POLICY user_api_tokens_select ON public.user_api_tokens FOR SELECT USING ((user_id = tf.current_user_id()));

REVOKE ALL ON public.user_api_tokens FROM PUBLIC;
REVOKE ALL ON public.user_api_tokens FROM anon, authenticated, service_role;

GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.user_api_tokens TO tf_app;


-- Unified spend view: one row-per-spend shape UNION-ing the messages ledger
-- (delegated conversations) and headless system jobs onto a single category
-- axis. Delegations split manual (per-user) from autonomous; system jobs are
-- 'system_overhead' with the job as subtype. source_id is cast to text so the
-- UNION's column type is uniform. security_invoker (PG 15+) is required so the
-- base tables' RLS applies under the querying app-pool identity.
CREATE VIEW public.llm_spend WITH (security_invoker='true') AS
 SELECT 'run'::text AS source,
    (m.id)::text AS source_id,
    m.org_id,
    c.team_id,
        CASE
            WHEN (c.trigger_type = 'manual'::text) THEN 'manual'::text
            ELSE 'autonomous'::text
        END AS category,
    NULL::text AS subtype,
    c.creator_user_id,
    c.actor_agent_id,
    c.trigger_id,
    m.model,
    COALESCE(m.cost_usd, (0)::real) AS total_cost_usd,
    COALESCE(m.input_tokens, 0) AS input_tokens,
    COALESCE(m.output_tokens, 0) AS output_tokens,
    COALESCE(m.cache_read_tokens, 0) AS cache_read_tokens,
    COALESCE(m.cache_creation_tokens, 0) AS cache_creation_tokens,
    m.created_at AS occurred_at
   FROM (public.messages m
     JOIN public.conversations c ON (((c.id = m.conversation_id) AND (c.org_id = m.org_id))))
  WHERE ((c.type = 'delegation'::text)
     AND ((m.role = 'assistant'::text) OR (m.cost_usd IS NOT NULL)))
UNION ALL

 SELECT 'system'::text AS source,
    (system_llm_runs.id)::text AS source_id,
    system_llm_runs.org_id,
    NULL::uuid AS team_id,
    'system_overhead'::text AS category,
    system_llm_runs.job AS subtype,
    NULL::uuid AS creator_user_id,
    NULL::uuid AS actor_agent_id,
    NULL::uuid AS trigger_id,
    system_llm_runs.model,
    system_llm_runs.total_cost_usd,
    system_llm_runs.input_tokens,
    system_llm_runs.output_tokens,
    system_llm_runs.cache_read_tokens,
    system_llm_runs.cache_creation_tokens,
    system_llm_runs.started_at AS occurred_at
   FROM public.system_llm_runs;

GRANT ALL ON TABLE public.llm_spend TO postgres;
GRANT ALL ON TABLE public.llm_spend TO anon;
GRANT ALL ON TABLE public.llm_spend TO authenticated;
GRANT ALL ON TABLE public.llm_spend TO service_role;
GRANT SELECT ON TABLE public.llm_spend TO tf_app;


-- tf_system: least-privilege executor role. The postgres-postinit-system
-- sidecar ALTERs it to LOGIN with TF_SYSTEM_PASSWORD once this migration has
-- applied. No DDL grant, ever. What follows is an enumerated allowlist of the
-- tables the executor touches; a migration adding a table to the executor's
-- code path must add its grant here, and the pgtest suites run role-bound.

GRANT USAGE ON SCHEMA public, tf TO tf_system;

-- Claim CAS / requeue / complete / resume stamps, plus the dispatcher's own
-- queue inserts. No DELETE — conversations are never removed, only terminated.
GRANT SELECT, INSERT, UPDATE ON TABLE public.conversations TO tf_system;
GRANT SELECT, INSERT, UPDATE ON TABLE public.messages TO tf_system;
GRANT USAGE, SELECT ON SEQUENCE public.messages_id_seq TO tf_system;
GRANT SELECT, INSERT, UPDATE ON TABLE public.artifacts TO tf_system;
GRANT SELECT, INSERT, DELETE ON TABLE public.conversation_worktrees TO tf_system;
GRANT SELECT, INSERT, UPDATE ON TABLE public.conversation_memory TO tf_system;
-- UPDATE backs the role-precedence upgrade (touched -> produced -> primary).
GRANT SELECT, INSERT, UPDATE ON TABLE public.conversation_memory_entities TO tf_system;
GRANT SELECT, INSERT ON TABLE public.external_actions TO tf_system;
GRANT SELECT, INSERT, UPDATE ON TABLE public.entities TO tf_system;
GRANT SELECT ON TABLE public.entity_links TO tf_system;
GRANT SELECT, INSERT ON TABLE public.task_events TO tf_system;
GRANT SELECT, UPDATE ON TABLE public.tasks TO tf_system;
-- Enqueued by the inject signal's gone-compensation; drain is router-side.
GRANT SELECT, INSERT ON TABLE public.pending_firings TO tf_system;
GRANT USAGE, SELECT ON SEQUENCE public.pending_firings_id_seq TO tf_system;
-- SELECT for the owning executor's apply-loop scan, UPDATE for ack. Insert and
-- the purge reaper are brain-gated, control-side only.
GRANT SELECT, UPDATE ON TABLE public.conversation_signals TO tf_system;
-- INSERT publishes a websocket event over the backplane; SELECT + DELETE are
-- the TTL reaper, which runs on every backplane-wired pod, executors included.
GRANT SELECT, INSERT, DELETE ON TABLE public.ws_outbox TO tf_system;
GRANT USAGE, SELECT ON SEQUENCE public.ws_outbox_id_seq TO tf_system;
-- SELECT for the PresentFor fast-deny fallback, DELETE for the presence
-- reaper. Executors never INSERT: the upserting heartbeat runs on HTTP pods.
GRANT SELECT, DELETE ON TABLE public.ws_presence TO tf_system;
-- Fleet registry: this instance's own register + heartbeat + drain flag.
GRANT SELECT, INSERT, UPDATE ON TABLE public.instances TO tf_system;
-- The per-pod sampler INSERTs a row a minute and the reaper DELETEs the tail.
GRANT SELECT, INSERT, DELETE ON TABLE public.instance_stats TO tf_system;
-- Same sampler and reaper, one row per live jail; SELECT serves usage reads.
GRANT SELECT, INSERT, DELETE ON TABLE public.sandbox_stats TO tf_system;
-- Granted here so the operator CLI works whichever admin role its pool binds.
GRANT SELECT, INSERT, DELETE ON TABLE public.operators TO tf_system;
-- SELECT-only: the post-step reactor reads an override for the conversation's
-- placement key. Writes are an operator action on a control pod.
GRANT SELECT ON TABLE public.placement_overrides TO tf_system;

-- The post-step reactor advances current_step_index and applies cancels; the
-- definition tables are read-only (a run executes off its frozen step_plan).
GRANT SELECT, UPDATE ON TABLE public.blueprint_runs TO tf_system;
GRANT SELECT ON TABLE public.blueprints TO tf_system;
GRANT SELECT ON TABLE public.blueprint_steps TO tf_system;
-- IncrementUsageSystem bumps a usage counter after resolving the step prompt.
GRANT SELECT, UPDATE ON TABLE public.prompts TO tf_system;
GRANT SELECT ON TABLE public.agents TO tf_system;

-- Read-only reference data the dispatcher resolves per run.
GRANT SELECT ON TABLE public.orgs TO tf_system;
GRANT SELECT ON TABLE public.org_settings TO tf_system;
-- GetSettingsSystem composes github/jira base_url + poll_interval from here,
-- so the per-run host and credential lookups need this read.
GRANT SELECT ON TABLE public.org_event_sources TO tf_system;
GRANT SELECT ON TABLE public.teams TO tf_system;
GRANT SELECT ON TABLE public.team_settings TO tf_system;
GRANT SELECT ON TABLE public.users TO tf_system;
-- GetGitHubLoginSystem (the manual-run co-author trailer) reads this.
GRANT SELECT ON TABLE public.user_github_identities TO tf_system;
GRANT SELECT ON TABLE public.team_github_repos TO tf_system;
-- UpdateCloneStatusSystem is local-mode-only in the current call graph,
-- granted ahead of the multi-mode bare-clone-cache path.
GRANT SELECT, UPDATE ON TABLE public.repositories TO tf_system;
GRANT SELECT ON TABLE public.org_github_apps TO tf_system;
GRANT SELECT ON TABLE public.org_github_app_installations TO tf_system;
GRANT SELECT ON TABLE public.events TO tf_system;
GRANT SELECT ON TABLE public.jira_project_status_rules TO tf_system;
-- llm_spend is security_invoker: reading it needs SELECT on its base tables
-- too, not just the view.
GRANT SELECT ON TABLE public.llm_spend TO tf_system;
GRANT SELECT ON TABLE public.system_llm_runs TO tf_system;
-- Slack provider policy ops resolve an authorization decision or a workspace
-- identity, never a bot token (that rides the sealed bundle). Read-only.
GRANT SELECT ON TABLE public.team_slack_channels TO tf_system;
GRANT SELECT ON TABLE public.slack_channels TO tf_system;
GRANT SELECT ON TABLE public.org_slack_workspaces TO tf_system;
-- The executor's schema-compatibility assert reads this; no DDL, ever.
GRANT SELECT ON TABLE public.goose_db_version TO tf_system;

-- +goose Down
SELECT 'down not supported';
